              >
                <q-icon :name="healthOverview.requestTrend > 0 ? 'trending_up' : healthOverview.requestTrend < 0 ? 'trending_down' : 'trending_flat'" />
                {{ healthOverview.requestTrend === 0 ? 'No change' : Math.abs(healthOverview.requestTrend) + '%' }}
              </div>
            </q-card-section>
          </q-card>
        </div>

        <!-- Error Rate -->
        <div class="col-12 col-sm-6 col-md-3">
          <q-card flat bordered class="stat-card">
            <q-card-section class="text-center">
              <div class="stat-icon">
                <q-icon name="error_outline" size="24px" :color="getErrorRateColor(healthOverview.errorRate)" />
              </div>
              <div
                class="stat-value text-h4 text-weight-bold"
                :class="getErrorRateTextClass(healthOverview.errorRate)"
              >
                <q-spinner v-if="isLoadingHealth" :color="getErrorRateColor(healthOverview.errorRate)" size="32px" />
                <span v-else>{{ healthOverview.errorRate.toFixed(1) }}%</span>
              </div>
              <div class="stat-label text-grey-7">Error Rate</div>
              <div class="threshold-indicator q-mt-xs text-caption text-grey-6">
                <q-icon name="check_circle" v-if="healthOverview.errorRate < 1" color="positive" />
                <q-icon name="warning" v-else-if="healthOverview.errorRate < 5" color="warning" />
                <q-icon name="error" v-else color="negative" />
                {{ healthOverview.errorRate < 1 ? 'Good' : healthOverview.errorRate < 5 ? 'Warning' : 'Critical' }}
              </div>
            </q-card-section>
          </q-card>
        </div>

        <!-- Response Time -->
        <div class="col-12 col-sm-6 col-md-3">
          <q-card flat bordered class="stat-card">
            <q-card-section class="text-center">
              <div class="stat-icon">
                <q-icon name="speed" size="24px" :color="getLatencyColor(healthOverview.p95ResponseTime)" />
              </div>
              <div
                class="stat-value text-h4 text-weight-bold"
                :class="getLatencyTextClass(healthOverview.p95ResponseTime)"
              >
                <q-spinner v-if="isLoadingHealth" color="primary" size="32px" />
                <span v-else>{{ healthOverview.avgResponseTime.toFixed(0) }}ms</span>
              </div>
              <div class="stat-label text-grey-7">Avg Response Time</div>
              <div class="p95-indicator q-mt-xs text-caption text-grey-6">
                P95: {{ healthOverview.p95ResponseTime.toFixed(0) }}ms
              </div>
            </q-card-section>
          </q-card>
        </div>
      </div>
    </div>

    <!-- Request Volume Chart -->
    <div class="charts-section q-pa-md">
      <q-card flat bordered class="chart-card">
        <q-card-section>
          <div class="chart-header">
            <div class="text-h6">Request Volume</div>
            <q-badge color="grey-4" text-color="grey-8">
              {{ getTimeRangeLabel() }}
            </q-badge>
          </div>
          <div v-if="isLoadingVolume" class="chart-loading">
            <q-spinner color="primary" size="48px" />
          </div>
          <apexchart
            v-else-if="volumeSeries[0].data.length > 0"
            type="area"
            height="300"
            :options="volumeChartOptions"
            :series="volumeSeries"
          />
          <div v-else class="no-data-message text-grey-6 text-center q-pa-xl">
            <q-icon name="info" size="48px" class="q-mb-md" />
            <div>No request volume data available for this time range</div>
          </div>
        </q-card-section>
      </q-card>
    </div>

    <!-- Response Time + Method Distribution Row -->
    <div class="q-pa-md">
      <div class="row q-col-gutter-md">
        <!-- Response Time Percentiles Chart -->
        <div class="col-12 col-md-8">
          <q-card flat bordered class="chart-card">
            <q-card-section>
              <div class="chart-header">
                <div class="text-h6">Response Time Percentiles</div>
              </div>
              <div v-if="isLoadingPercentiles" class="chart-loading">
                <q-spinner color="primary" size="48px" />
              </div>
              <apexchart
                v-else-if="percentilesSeries[0].data.length > 0"
                type="line"
                height="300"
                :options="percentilesChartOptions"
                :series="percentilesSeries"
              />
              <div v-else class="no-data-message text-grey-6 text-center q-pa-xl">
                <q-icon name="info" size="48px" class="q-mb-md" />
                <div>No response time data available</div>
              </div>
            </q-card-section>
          </q-card>
        </div>

        <!-- Method Distribution Chart -->
        <div class="col-12 col-md-4">
          <q-card flat bordered class="chart-card">
            <q-card-section>
              <div class="chart-header">
                <div class="text-h6">Request Methods</div>
              </div>
              <div v-if="isLoadingMethods" class="chart-loading">
                <q-spinner color="primary" size="48px" />
              </div>
              <apexchart
                v-else-if="methodSeries.length > 0"
                type="donut"
                height="300"
                :options="methodChartOptions"
                :series="methodSeries"
              />
              <div v-else class="no-data-message text-grey-6 text-center q-pa-xl">
                <q-icon name="info" size="48px" class="q-mb-md" />
                <div>No method data available</div>
              </div>
            </q-card-section>
          </q-card>
        </div>
      </div>
    </div>

    <!-- Top Slowest Endpoints -->
    <div class="q-pa-md">
      <q-card flat bordered class="chart-card">
        <q-card-section>
          <div class="chart-header">
            <div>
              <div class="text-h6">Top 10 Slowest Endpoints</div>
              <div class="text-caption text-grey-6">
                Click any bar to open Grafana Tempo filtered by host + method
              </div>
            </div>
            <div class="row q-gutter-xs items-center">
              <q-badge v-if="envSlug" color="info" text-color="white">
                {{ envSlug }} only
                <q-tooltip>
                  Showing only endpoints whose host matches the current
                  environment ({{ envSlug }}). The dev Loki currently also
                  receives sandbox telemetry — see DOCB-12312 for the
                  infrastructure fix.
                </q-tooltip>
              </q-badge>
              <q-badge color="warning" text-color="white">
                by P95 Response Time
              </q-badge>
            </div>
          </div>
          <div v-if="isLoadingEndpoints" class="chart-loading">
            <q-spinner color="primary" size="48px" />
          </div>
          <apexchart
            v-else-if="endpointsSeries[0].data.length > 0"
            type="bar"
            height="400"
            :options="endpointsChartOptions"
            :series="endpointsSeries"
          />
          <div v-else class="no-data-message text-grey-6 text-center q-pa-xl">
            <q-icon name="info" size="48px" class="q-mb-md" />
            <div>No endpoint performance data available</div>
          </div>
        </q-card-section>
      </q-card>
    </div>

    <!-- Slow Requests with Traces -->
    <div class="q-pa-md">
      <q-card flat bordered class="chart-card">
        <q-card-section>
          <div class="chart-header">
            <div>
              <div class="text-h6">Slow Requests with Traces</div>
              <div class="text-caption text-grey-6">
                20 slowest individual requests in the selected range — click trace to open Grafana Tempo
              </div>
            </div>
            <div class="row q-gutter-xs items-center">
              <q-badge v-if="envSlug" color="info" text-color="white">{{ envSlug }} only</q-badge>
              <q-btn
                flat
                dense
                no-caps
                icon="content_copy"
                label="Copy all JSON"
                size="sm"
                :disable="slowRequests.length === 0"
                @click="copyAllSlowRequestsJson"
              />
            </div>
          </div>
          <div v-if="isLoadingSlowRequests" class="chart-loading">
            <q-spinner color="primary" size="48px" />
          </div>
          <q-table
            v-else-if="slowRequests.length > 0"
            :rows="slowRequests"
            :columns="slowRequestColumns"
            row-key="timestamp"
            dense
            flat
            :rows-per-page-options="[10, 20, 50]"
            :pagination="{ rowsPerPage: 20, sortBy: 'durationMs', descending: true }"
          >
            <template v-slot:body-cell-url="props">
              <q-td :props="props" class="ellipsis" style="max-width: 420px">
                <span :title="props.row.url">{{ props.row.url }}</span>
              </q-td>
            </template>
            <template v-slot:body-cell-statusCode="props">
              <q-td :props="props">
                <q-badge
                  :color="props.row.statusCode >= 500 ? 'negative' : props.row.statusCode >= 400 ? 'warning' : 'positive'"
                  text-color="white"
                >
                  {{ props.row.statusCode || '?' }}
                </q-badge>
              </q-td>
            </template>
            <template v-slot:body-cell-timestamp="props">
              <q-td :props="props">
                <span class="text-caption">{{ new Date(props.row.timestamp).toLocaleString() }}</span>
              </q-td>
            </template>
            <template v-slot:body-cell-actions="props">
              <q-td :props="props">
                <q-btn
                  v-if="props.row.traceId"
                  dense
                  flat
                  size="sm"
                  icon="open_in_new"
                  color="primary"
                  @click="openTempoForTrace(props.row.traceId)"
                >
                  <q-tooltip>Open trace in Grafana Tempo</q-tooltip>
                </q-btn>
                <q-btn
                  dense
                  flat
                  size="sm"
                  icon="content_copy"
                  @click="copyRequestJson(props.row)"
                >
                  <q-tooltip>Copy this request as JSON</q-tooltip>
                </q-btn>
              </q-td>
            </template>
          </q-table>
          <div v-else class="no-data-message text-grey-6 text-center q-pa-xl">
