            <div>No slow requests captured in this range</div>
          </div>
        </q-card-section>
      </q-card>
    </div>

    <!-- Faro Unavailable Notice -->
    <div v-if="!isFaroAvailable" class="q-pa-md">
      <q-banner class="bg-warning text-white" rounded>
        <template v-slot:avatar>
          <q-icon name="warning" />
        </template>
        <div class="text-subtitle1">Limited Data Available</div>
        <div class="text-body2">
          Faro real-user monitoring is not configured for this environment.
          Some API metrics may be unavailable or show placeholder data.
        </div>
