</template>

<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { useQuasar } from 'quasar';
import VueApexCharts from 'vue3-apexcharts';
import ApiMetricsService, {
  type ApiHealthOverview,
  type RequestVolumePoint,
  type ResponseTimePercentiles,
  type MethodDistribution,
  type SlowRequestEntry,
  getCurrentEnvSlug,
  buildTempoTraceUrl,
  buildTempoSearchUrl,
} from 'src/services/analytics/ApiMetricsService';
import type { ApiEndpointSummary } from 'src/services/faro/types';
import { copyToClipboard } from 'quasar';

// ============================================================================
// Component Setup
// ============================================================================

const apexchart = VueApexCharts;
const $q = useQuasar();
const apiMetricsService = new ApiMetricsService();

// ============================================================================
// State
// ============================================================================

// Time filter
const selectedTimePreset = ref('1h');
const timePresetOptions = [
  { label: 'Last Hour', value: '1h' },
  { label: 'Last 6 Hours', value: '6h' },
  { label: 'Last 24 Hours', value: '24h' },
  { label: 'Last 7 Days', value: '7d' },
  { label: 'Last 30 Days', value: '30d' },
];

// Loading states
const isLoading = ref(false);
const isLoadingHealth = ref(false);
const isLoadingVolume = ref(false);
const isLoadingPercentiles = ref(false);
const isLoadingMethods = ref(false);
const isLoadingEndpoints = ref(false);

// Data
const isFaroAvailable = ref(true);
const healthOverview = ref<ApiHealthOverview>({
  healthScore: 0,
  healthCategory: 'poor',
  totalRequests: 0,
  requestTrend: 0,
  errorRate: 0,
  errorTrend: 0,
  avgResponseTime: 0,
  p95ResponseTime: 0,
});

const requestVolume = ref<RequestVolumePoint[]>([]);
const responsePercentiles = ref<ResponseTimePercentiles>({
  timestamps: [],
  p50: [],
  p75: [],
  p95: [],
  p99: [],
});
const methodDistribution = ref<MethodDistribution[]>([]);
const slowEndpoints = ref<ApiEndpointSummary[]>([]);
const slowRequests = ref<SlowRequestEntry[]>([]);
const isLoadingSlowRequests = ref(false);
const envSlug = ref<string | null>(getCurrentEnvSlug());

const slowRequestColumns = [
  { name: 'method', label: 'Method', field: 'method', align: 'left' as const, style: 'width: 60px' },
  { name: 'host', label: 'Host', field: 'host', align: 'left' as const, style: 'min-width: 180px' },
  { name: 'url', label: 'URL', field: 'url', align: 'left' as const, style: 'min-width: 280px; max-width: 420px' },
  { name: 'durationMs', label: 'Duration', field: 'durationMs', align: 'right' as const, sortable: true, format: (v: number) => `${v} ms` },
  { name: 'statusCode', label: 'Status', field: 'statusCode', align: 'center' as const, style: 'width: 80px' },
  { name: 'timestamp', label: 'When', field: 'timestamp', align: 'left' as const, style: 'width: 160px' },
  { name: 'actions', label: 'Actions', field: 'traceId', align: 'center' as const, style: 'width: 140px' },
];

function openTempoForTrace(traceId: string): void {
  const url = buildTempoTraceUrl(traceId);
  if (url) window.open(url, '_blank', 'noopener');
}

function openTempoForEndpoint(host: string, method: string): void {
  const url = buildTempoSearchUrl(host, method, 60);
  if (url) window.open(url, '_blank', 'noopener');
}

async function copyRequestJson(entry: SlowRequestEntry): Promise<void> {
  try {
    await copyToClipboard(JSON.stringify(entry, null, 2));
    $q.notify({ type: 'positive', message: 'Request JSON copied', position: 'top', timeout: 1500 });
  } catch {
    $q.notify({ type: 'negative', message: 'Copy failed', position: 'top', timeout: 2000 });
  }
}

async function copyAllSlowRequestsJson(): Promise<void> {
  try {
    await copyToClipboard(JSON.stringify(slowRequests.value, null, 2));
    $q.notify({ type: 'positive', message: `${slowRequests.value.length} entries copied`, position: 'top', timeout: 1500 });
  } catch {
    $q.notify({ type: 'negative', message: 'Copy failed', position: 'top', timeout: 2000 });
  }
}

// ============================================================================
// Computed - Chart Data
// ============================================================================

const volumeSeries = computed(() => [
  {
    name: 'Requests/min',
    data: requestVolume.value.map((point) => ({
      x: new Date(point.timestamp).getTime(),
      y: point.requestsPerMinute,
    })),
  },
]);

const volumeChartOptions = computed(() => ({
  chart: {
    type: 'area' as const,
    toolbar: { show: false },
    background: 'transparent',
  },
  colors: ['#3b82f6'],
  stroke: { curve: 'smooth' as const, width: 2 },
  fill: {
    type: 'gradient',
    gradient: {
      shadeIntensity: 1,
      opacityFrom: 0.4,
      opacityTo: 0.1,
      stops: [0, 100],
    },
  },
  xaxis: {
    type: 'datetime' as const,
    labels: {
      datetimeUTC: false,
      style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' },
    },
  },
  yaxis: {
    title: { text: 'Requests/min', style: { color: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
    labels: { style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
  },
  tooltip: {
    theme: $q.dark.isActive ? 'dark' : 'light',
    x: { format: 'MMM dd, HH:mm' },
  },
  grid: {
    borderColor: $q.dark.isActive ? '#374151' : '#e5e7eb',
  },
}));

const percentilesSeries = computed(() => [
  { name: 'P50', data: responsePercentiles.value.p50.map((v, i) => ({ x: new Date(responsePercentiles.value.timestamps[i]).getTime(), y: v })) },
  { name: 'P75', data: responsePercentiles.value.p75.map((v, i) => ({ x: new Date(responsePercentiles.value.timestamps[i]).getTime(), y: v })) },
  { name: 'P95', data: responsePercentiles.value.p95.map((v, i) => ({ x: new Date(responsePercentiles.value.timestamps[i]).getTime(), y: v })) },
  { name: 'P99', data: responsePercentiles.value.p99.map((v, i) => ({ x: new Date(responsePercentiles.value.timestamps[i]).getTime(), y: v })) },
]);

const percentilesChartOptions = computed(() => ({
  chart: {
    type: 'line' as const,
    toolbar: { show: false },
    background: 'transparent',
  },
  colors: ['#10b981', '#f59e0b', '#ef4444', '#8b5cf6'],
  stroke: { width: [2, 2, 2, 2], dashArray: [0, 0, 0, 5] },
  xaxis: {
    type: 'datetime' as const,
    labels: {
      datetimeUTC: false,
      style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' },
    },
  },
  yaxis: {
    title: { text: 'Response Time (ms)', style: { color: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
    labels: { style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
  },
  legend: {
    position: 'top' as const,
    labels: { colors: $q.dark.isActive ? '#9ca3af' : '#374151' },
  },
  tooltip: {
    theme: $q.dark.isActive ? 'dark' : 'light',
    y: { formatter: (val: number) => `${val.toFixed(1)} ms` },
  },
  grid: {
    borderColor: $q.dark.isActive ? '#374151' : '#e5e7eb',
  },
}));

const methodSeries = computed(() => methodDistribution.value.map((m) => m.count));

const methodChartOptions = computed(() => ({
  chart: {
    type: 'donut' as const,
    background: 'transparent',
  },
  colors: ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'],
  labels: methodDistribution.value.map((m) => m.method),
  legend: {
    position: 'bottom' as const,
    labels: { colors: $q.dark.isActive ? '#9ca3af' : '#374151' },
  },
  plotOptions: {
    pie: {
      donut: {
        size: '65%',
        labels: {
          show: true,
          total: {
            show: true,
            label: 'Total',
            color: $q.dark.isActive ? '#9ca3af' : '#374151',
          },
        },
      },
    },
  },
  tooltip: {
    theme: $q.dark.isActive ? 'dark' : 'light',
    y: {
      formatter: (val: number, opts: { seriesIndex: number }) => {
        const method = methodDistribution.value[opts.seriesIndex];
        return `${val} (${method?.percentage || 0}%)`;
      },
    },
  },
}));

const endpointsSeries = computed(() => [
  {
    name: 'P95 Response Time (ms)',
    data: slowEndpoints.value.map((e) => e.p95),
  },
]);

const endpointsChartOptions = computed(() => ({
  chart: {
    type: 'bar' as const,
    toolbar: { show: false },
    background: 'transparent',
    events: {
      dataPointSelection: (_e: unknown, _ctx: unknown, config: { dataPointIndex: number }) => {
        const idx = config.dataPointIndex;
        const endpoint = slowEndpoints.value[idx];
        if (endpoint) openTempoForEndpoint(endpoint.endpoint, endpoint.method);
      },
    },
  },
  colors: ['#ef4444'],
  plotOptions: {
    bar: {
      horizontal: true,
      barHeight: '70%',
      borderRadius: 4,
    },
  },
  xaxis: {
    title: { text: 'Response Time (ms)', style: { color: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
    labels: { style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
    categories: slowEndpoints.value.map((e) => {
      const label = `${e.method} ${e.endpoint}`;
      // Truncate long endpoint names
      return label.length > 40 ? label.substring(0, 37) + '...' : label;
    }),
  },
  yaxis: {
    labels: {
      style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' },
    },
  },
  tooltip: {
    theme: $q.dark.isActive ? 'dark' : 'light',
    y: {
      formatter: (val: number, opts: { dataPointIndex: number }) => {
        const endpoint = slowEndpoints.value[opts.dataPointIndex];
        return `${val.toFixed(0)} ms (${endpoint?.count || 0} requests, ${endpoint?.successRate || 0}% success)`;
      },
    },
  },
  grid: {
    borderColor: $q.dark.isActive ? '#374151' : '#e5e7eb',
  },
}));

// ============================================================================
// Helper Functions
// ============================================================================

function getHoursFromPreset(preset: string): number {
  const match = preset.match(/^(\d+)([hd])$/);
  if (!match) return 1;
  const value = parseInt(match[1], 10);
  const unit = match[2];
  return unit === 'd' ? value * 24 : value;
}

function getTimeRangeLabel(): string {
  const option = timePresetOptions.find((o) => o.value === selectedTimePreset.value);
  return option?.label || 'Last Hour';
}

function formatNumber(num: number): string {
  if (num >= 1000000) {
    return `${(num / 1000000).toFixed(1)}M`;
  }
  if (num >= 1000) {
    return `${(num / 1000).toFixed(1)}K`;
  }
  return num.toString();
}

function getHealthColor(category: string): string {
  switch (category) {
    case 'excellent':
      return 'positive';
    case 'good':
      return 'primary';
    case 'fair':
      return 'warning';
    case 'poor':
      return 'negative';
    default:
      return 'grey';
  }
}

function getHealthTextClass(category: string): string {
  switch (category) {
    case 'excellent':
      return 'text-positive';
    case 'good':
      return 'text-primary';
    case 'fair':
      return 'text-warning';
    case 'poor':
      return 'text-negative';
    default:
      return 'text-grey';
  }
}

function getErrorRateColor(rate: number): string {
  if (rate < 1) return 'positive';
  if (rate < 5) return 'warning';
  return 'negative';
}

function getErrorRateTextClass(rate: number): string {
  if (rate < 1) return 'text-positive';
  if (rate < 5) return 'text-warning';
  return 'text-negative';
}

function getLatencyColor(p95: number): string {
  if (p95 < 500) return 'positive';
  if (p95 < 1000) return 'warning';
  return 'negative';
}

function getLatencyTextClass(p95: number): string {
  if (p95 < 500) return 'text-positive';
  if (p95 < 1000) return 'text-warning';
  return 'text-negative';
}

// ============================================================================
// Data Loading Functions
// ============================================================================

async function loadHealthOverview() {
  isLoadingHealth.value = true;
  try {
    const hours = getHoursFromPreset(selectedTimePreset.value);
    healthOverview.value = await apiMetricsService.getApiHealthOverview(hours);
  } catch (error) {
    console.error('[ApiMetricsTab] Failed to load health overview:', error);
  } finally {
    isLoadingHealth.value = false;
  }
}

async function loadRequestVolume() {
  isLoadingVolume.value = true;
  try {
    const hours = getHoursFromPreset(selectedTimePreset.value);
    requestVolume.value = await apiMetricsService.getRequestVolume(hours);
  } catch (error) {
    console.error('[ApiMetricsTab] Failed to load request volume:', error);
    requestVolume.value = [];
  } finally {
    isLoadingVolume.value = false;
  }
}

async function loadResponsePercentiles() {
  isLoadingPercentiles.value = true;
  try {
    const hours = getHoursFromPreset(selectedTimePreset.value);
    responsePercentiles.value = await apiMetricsService.getResponseTimePercentiles(hours);
  } catch (error) {
    console.error('[ApiMetricsTab] Failed to load response percentiles:', error);
    responsePercentiles.value = { timestamps: [], p50: [], p75: [], p95: [], p99: [] };
  } finally {
    isLoadingPercentiles.value = false;
  }
}

async function loadMethodDistribution() {
  isLoadingMethods.value = true;
  try {
    const hours = getHoursFromPreset(selectedTimePreset.value);
    methodDistribution.value = await apiMetricsService.getMethodDistribution(hours);
  } catch (error) {
    console.error('[ApiMetricsTab] Failed to load method distribution:', error);
    methodDistribution.value = [];
  } finally {
    isLoadingMethods.value = false;
  }
}

async function loadSlowEndpoints() {
  isLoadingEndpoints.value = true;
  try {
    const hours = getHoursFromPreset(selectedTimePreset.value);
    slowEndpoints.value = await apiMetricsService.getTopSlowEndpoints(hours, 10);
  } catch (error) {
    console.error('[ApiMetricsTab] Failed to load slow endpoints:', error);
    slowEndpoints.value = [];
  } finally {
    isLoadingEndpoints.value = false;
  }
}

async function loadSlowRequests() {
  isLoadingSlowRequests.value = true;
  try {
    const hours = getHoursFromPreset(selectedTimePreset.value);
    slowRequests.value = await apiMetricsService.getSlowestRequestsWithTraces(hours, 20);
  } catch (error) {
    console.error('[ApiMetricsTab] Failed to load slow requests with traces:', error);
    slowRequests.value = [];
  } finally {
    isLoadingSlowRequests.value = false;
  }
}

async function refreshAllData() {
  isLoading.value = true;
  isFaroAvailable.value = apiMetricsService.isAvailable();

  await Promise.allSettled([
    loadHealthOverview(),
    loadRequestVolume(),
    loadResponsePercentiles(),
    loadMethodDistribution(),
    loadSlowEndpoints(),
    loadSlowRequests(),
  ]);

  isLoading.value = false;
}

function onTimePresetChange() {
  refreshAllData();
}

// ============================================================================
// Lifecycle
// ============================================================================

onMounted(() => {
  refreshAllData();
});
</script>

