const hoursSinceMidnight = (): number => {
  const now = new Date();
  const midnight = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  return Math.max(1, Math.ceil((now.getTime() - midnight.getTime()) / (60 * 60 * 1000)));
};

// Time Range Presets
const timePresetOptions = computed(() => [
  {
    label: t.value('last_hour'),
    value: 'last_hour',
    hours: 1,
  },
  // 'today' = since local midnight (NOT a fixed 24h window). The previous
  // value of 24h forced every Faro/Loki query to span a full day, which
  // pushed the substring-filter LogQL above the 10s axios timeout when the
  // cluster runs Loki in monolithic mode.
  { label: t.value('today'), value: 'today', hours: hoursSinceMidnight() },
  {
    label: t.value('last_7_days'),
    value: 'last_7_days',
    hours: 168,
