const toggleSeverity = (severity: string) => {
  // Use immutable operations to avoid need for deep watcher
  if (selectedSeverities.value.includes(severity)) {
    // Immutable removal using filter
    selectedSeverities.value = selectedSeverities.value.filter((s) => s !== severity);
  } else {
    // Immutable addition using spread
    selectedSeverities.value = [...selectedSeverities.value, severity];
  }
  updateUrlParams();
};

/**
 * Update URL query parameters without adding to browser history
 */
const updateUrlParams = () => {
  const query: Record<string, string> = {};

  // Include active tab (only if not default 'logs')
  if (activeTab.value !== 'logs') {
    query.tab = activeTab.value;
  }

  // If auth tab, include auth-specific params
  if (activeTab.value === 'auth') {
    if (authTimePeriod.value !== 'today') {
      query.auth_period = authTimePeriod.value;
    }
  } else {
    // Logs tab - include existing parameters
    // Include time preset (only if not default 'today')
    if (selectedTimePreset.value && selectedTimePreset.value !== 'today') {
      query.time_preset = selectedTimePreset.value;
    }

    // Include custom date range if preset is 'custom'
    if (selectedTimePreset.value === 'custom') {
      if (customStartDate.value) {
        query.start_date = customStartDate.value;
      }
      if (customEndDate.value) {
        query.end_date = customEndDate.value;
      }
    }

    // Include non-default filters
    if (selectedSeverities.value.length > 0 && selectedSeverities.value.length < 4) {
      query.log_level = selectedSeverities.value.join(',');
    }

    if (selectedServices.value.length > 0) {
      query.services = selectedServices.value.join(',');
    }
  }

  // Use replace() to avoid cluttering browser history
  router.replace({ path: route.path, query }).catch(err => {
    // Ignore NavigationDuplicated errors
    if (err.name !== 'NavigationDuplicated') {
      console.error('[ANALYTICS] URL update error:', err);
    }
  });

  console.log('[ANALYTICS] Updated URL:', query);
};

/**
 * Load state from URL query parameters
 */
const loadFromUrlParams = () => {
  const query = route.query;

  // Parse active tab
  if (query.tab === 'auth') {
    activeTab.value = 'auth';
  } else if (query.tab === 'api') {
    activeTab.value = 'api';
  } else if (query.tab === 'executive' && isAdminUser.value) {
    activeTab.value = 'executive';
  }
  // Quality tab removed - was not working properly

  // Parse auth time period
  if (query.auth_period && ['today', 'week', '30days'].includes(String(query.auth_period))) {
    authTimePeriod.value = String(query.auth_period) as 'today' | 'week' | '30days';
  }

  // Parse log levels
  if (query.log_level) {
    const levels = String(query.log_level).split(',').map(l => l.trim().toUpperCase());
    const valid = levels.filter(l => ['ERROR', 'WARN', 'INFO', 'DEBUG'].includes(l));
    if (valid.length > 0) {
      selectedSeverities.value = valid;
    }
  }

  // Parse services
  if (query.services) {
    selectedServices.value = String(query.services).split(',').map(s => s.trim());
  }

  // Parse time preset
  if (query.time_preset) {
    const preset = String(query.time_preset);
    const validPresets = ['last_hour', 'today', 'last_7_days', 'last_30_days', 'custom'];
    if (validPresets.includes(preset)) {
      selectedTimePreset.value = preset;
    }
  }

  // Parse custom date range
  if (query.start_date) {
    customStartDate.value = String(query.start_date);
  }
  if (query.end_date) {
    customEndDate.value = String(query.end_date);
  }

  console.log('[ANALYTICS] Initialized from URL:', {
    activeTab: activeTab.value,
    authTimePeriod: authTimePeriod.value,
    severities: selectedSeverities.value,
    services: selectedServices.value,
    timePreset: selectedTimePreset.value,
    customStartDate: customStartDate.value,
    customEndDate: customEndDate.value,
  });
};

/**
 * Load organization logs metrics (severity counts)
 */
const loadMetrics = async () => {
  if (metricsLoading.value) return;

  metricsLoading.value = true;

  try {
    // Calculate time range for metrics query
    let hours = 1;
    if (selectedTimePreset.value === 'last_hour') {
      hours = 1;
    } else if (selectedTimePreset.value === 'today') {
      hours = 24;
    } else if (selectedTimePreset.value === 'last_7_days') {
      hours = 168;
    } else if (selectedTimePreset.value === 'last_30_days') {
      hours = 720; // 30 days = 720 hours (will be capped at 24 by backend)
    } else if (selectedTimePreset.value === 'custom') {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Build metrics API parameters
    const params: any = {
      hours_per_page: hours, // Send actual hours from time range selection
    };

    // Add severity filter
    if (
      selectedSeverities.value.length > 0 &&
      selectedSeverities.value.length < 4
    ) {
      params.log_level = selectedSeverities.value.join(',');
    }

    // Add service filter
    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    // Fetch metrics
    const response = await activityLogsApiService.getOrganizationMetrics(params);

    // API returns counts in nested severity_counts object
    const errorCount = response.severity_counts?.error_count ?? 0;
    const warningCount = response.severity_counts?.warning_count ?? 0;
    const infoCount = response.severity_counts?.info_count ?? 0;
    const debugCount = response.severity_counts?.debug_count ?? 0;
    const totalCount = response.severity_counts?.total ?? 0;

    // Extract peak activity and top source from API response
    const peakActivity = response.peak_activity || { time: '-', count: 0 };
    const topSource = response.top_source || { name: '-', count: 0 };

    // Update stats with API response
    logStats.value = {
      total: totalCount || 0,
      error: errorCount || 0,
      warn: warningCount || 0,
      info: infoCount || 0,
      debug: debugCount || 0,
      topSource: topSource,
      peakTime: peakActivity,
    };

    console.log('[ANALYTICS] Loaded metrics:', {
      params,
      response,
      stats: logStats.value,
    });
  } catch (error) {
    console.error('[ANALYTICS] Error loading metrics:', error);
    // Don't show error notification for metrics - logs still work
    // Metrics will show 0 if this fails
  } finally {
    metricsLoading.value = false;
  }
};

/**
 * Load timeline data from Combined Analytics API (OpenSearch + Loki/Faro)
 *
 * Queries both backend logs (OpenSearch) and frontend RUM logs (Faro/Loki)
 * and merges them into a unified timeline for the "Logs Over Time" chart.
 */
const loadTimelineData = async () => {
  try {
    // Calculate hours from selected time range
    let hours = 1;
    const preset = timePresetOptions.value.find(
      (p) => p.value === selectedTimePreset.value,
    );
    if (preset && preset.value !== 'custom') {
      hours = preset.hours;
    } else if (customStartDate.value && customEndDate.value) {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Use new service-timeline endpoint for "Logs Over Time by Service"
    const params: any = {
      hours: hours,
      bucket: hours <= 168 ? 'hour' : 'day', // Auto-switch to day for > 7 days
      top_n: 10, // Top 10 services
    };

    // Add service filters
    if (selectedServices.value.length > 0) {
      params.services = selectedServices.value.join(',');
    }

    console.log('[ANALYTICS] Loading service timeline data:', params);

    // Call new service-timeline endpoint
    const response = await activityLogsApiService.getServiceTimelineAnalytics(params);

    // Store service list and totals for chart legend and tooltips
    serviceTimelineServices.value = response.services || [];
    serviceTimelineTotals.value = response.totals || {};

    // Transform response to chart format
    // Each timeline entry has: { hour: "2025-01-16T10:00:00Z", services: { api: { error: 5, warning: 10, ... }, ... } }
    timeseriesData.value = response.timeline.map((point: any) => ({
      timestamp: point.hour,
      services: point.services || {},
    }));

    // Set interval based on bucket
    timeseriesInterval.value = response.bucket === 'hour' ? '1-hour' : '1-day';

    console.log('[ANALYTICS] Service timeline data loaded:', {
      buckets: timeseriesData.value.length,
      interval: timeseriesInterval.value,
      totalCount: response.total_count,
      services: serviceTimelineServices.value,
    });

  } catch (error: any) {
    console.error('[ANALYTICS] Failed to load service timeline data:', error);
    // Fallback to combined analytics if service-timeline endpoint fails
    try {
      console.log('[ANALYTICS] Falling back to combined analytics...');
      const fallbackResponse = await activityLogsApiService.getCombinedAnalytics({
        hours: 24,
        bucket: 'hour',
        group_by: 'level',
        format: 'timeline',
        include_faro: true,
      });
      // Reset service data
      serviceTimelineServices.value = [];
      serviceTimelineTotals.value = {};
      // Use level-based fallback format
      timeseriesData.value = fallbackResponse.timeline.map((point: any) => ({
        timestamp: point.hour,
        error: point.error || 0,
        warn: point.warning || 0,
        info: point.info || 0,
        debug: point.debug || 0,
      }));
      timeseriesInterval.value = '1-hour';
    } catch (fallbackError) {
      console.error('[ANALYTICS] Fallback also failed:', fallbackError);
      timeseriesData.value = [];
      serviceTimelineServices.value = [];
      serviceTimelineTotals.value = {};
    }
  }
};

/**
 * Load service breakdown data for Analytics tab
 * Uses the logs services endpoint to get service-level aggregations
 */
const loadServiceData = async () => {
  try {
    // Calculate time range for service query
    let hours = 24;
    if (selectedTimePreset.value === 'last_hour') {
      hours = 1;
    } else if (selectedTimePreset.value === 'today') {
      hours = 24;
    } else if (selectedTimePreset.value === 'last_7_days') {
      hours = 168;
    } else if (selectedTimePreset.value === 'last_30_days') {
      hours = 720;
    } else if (selectedTimePreset.value === 'custom' && customStartDate.value && customEndDate.value) {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Build parameters
    const params: any = {};

    // Determine time period based on hours
    if (hours <= 24) {
      params.time_period = 'today';
    } else if (hours <= 168) {
      params.time_period = 'week';
    } else {
      params.time_period = '30days';
    }

    // Add severity filter
    if (selectedSeverities.value.length > 0 && selectedSeverities.value.length < 4) {
      params.log_level = selectedSeverities.value.join(',');
    }

    console.log('[ANALYTICS] Loading service data:', params);

    // Fetch service data
    const response = await activityLogsApiService.getLogsServices(params);

    // Transform response to chart format - combine apps, components, and services
    // Backend returns all three arrays with different field names from OpenSearch
    // We need to merge them to show complete service breakdown
    if (response) {
      // Combine all service types from backend response
      const sources = [
        ...(response.apps || []),
        ...(response.components || []),
        ...(response.services || []),
      ];

      // Normalize known service name aliases and case to avoid duplicate chart entries
      const normalizeServiceName = (name: string): string => {
        const lower = name.toLowerCase();
        const aliases: Record<string, string> = {
          'docbits-web': 'web',
        };
        return aliases[lower] || lower;
      };

      // Deduplicate by name, keeping highest total (same service may appear in multiple arrays)
      const serviceMap = new Map<string, number>();
      for (const s of sources) {
        const name = normalizeServiceName(s.name || 'Unknown');
        const total = s.total || 0;
        const existing = serviceMap.get(name) || 0;
        serviceMap.set(name, Math.max(existing, total));
      }

      serviceBreakdownData.value = Array.from(serviceMap.entries())
        .map(([service, total]) => ({ service, total }))
        .sort((a, b) => b.total - a.total)
        .slice(0, 12);

      console.log('[ANALYTICS] Service data loaded:', {
        count: serviceBreakdownData.value.length,
        sources: {
          apps: response.apps?.length || 0,
          components: response.components?.length || 0,
          services: response.services?.length || 0,
        },
        data: serviceBreakdownData.value,
      });
    } else {
      serviceBreakdownData.value = [];
    }
  } catch (error: any) {
    console.warn('[ANALYTICS] Failed to load service data:', error);
    serviceBreakdownData.value = [];
  }
};

/**
 * Timeout wrapper for API calls
 * Prevents infinite loading spinners
 */
const withTimeout = async <T>(
  promise: Promise<T>,
  timeoutMs: number = 30000,
  errorMessage: string = 'Request timed out'
): Promise<T> => {
  return Promise.race([
    promise,
    new Promise<T>((_, reject) =>
      setTimeout(() => reject(new Error(errorMessage)), timeoutMs)
    ),
  ]);
};

/**
 * Load Faro-based metrics for Analytics tab
 * Uses Promise.allSettled to handle partial failures gracefully
 */
const loadNewMetrics = async () => {
  newMetricsLoading.value = true;
  metricsErrors.value = [];

  // Check if Faro is available
  faroAvailable.value = isFaroAvailable();

  if (!faroAvailable.value) {
    console.warn('[ANALYTICS] Faro not available in this environment');
    newMetricsLoading.value = false;
    return;
  }

  try {
    // Determine time range based on preset or custom range
    let hours = 1;
    const preset = timePresetOptions.value.find(
      (p) => p.value === selectedTimePreset.value,
    );
    if (preset && preset.value !== 'custom') {
      hours = preset.hours;
    } else if (
      selectedTimePreset.value === 'custom' &&
      customStartDate.value &&
      customEndDate.value
    ) {
      const start = new Date(customStartDate.value);
      const end = new Date(customEndDate.value);
      hours = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60));
    }

    // Convert hours to Faro time range format (e.g., '1h', '24h', '7d')
    const timeRange = hours >= 168 ? `${Math.floor(hours / 24)}d` : `${hours}h`;
    const params = { timeRange };

    // J1 JS Errors trace widget — loads in parallel, fails soft (empty table,
    // no toast). Range is capped inside the service at 24h regardless.
    isLoadingJsErrors.value = true;
    getJsErrorsWithStacks(Math.min(hours, 24), 20)
      .then((entries) => {
        jsErrorEntries.value = entries;
      })
      .catch((err) => {
        console.warn('[ANALYTICS] JS errors widget failed:', err);
        jsErrorEntries.value = [];
      })
      .finally(() => {
        isLoadingJsErrors.value = false;
      });

    console.log('[ANALYTICS] Loading Faro metrics:', { timeRange, hours });

    // Load all 8 Faro widgets concurrently. The previous serial `for…of`
    // (followup-7) was over-defensive: with LOKI_MAX_CONCURRENT raised to 8
    // and the cluster on 3 replicas, concurrency is already bounded inside
    // FaroMetricsService.lokiHttp. Going parallel cuts wall-clock from
    // ~25 s → ~5 s at 7 d (and ~40 s → ~12 s at 30 d). Reactivity makes
    // each widget render as soon as its data lands.
    const metricNames = [
      'Core Web Vitals',
      'Page Performance',
      'Error Analysis',
      'User Activity',
      'Dashboard Performance',
      'WebSocket Performance',
      'API Performance',
      'Browser Analytics',
    ];
    const results = await Promise.allSettled([
      withTimeout(getCoreWebVitals(params), 30000, 'Core Web Vitals timed out'),
      withTimeout(getPagePerformance(params), 30000, 'Page Performance timed out'),
      withTimeout(getErrorMetrics(params), 30000, 'Error Analysis timed out'),
      withTimeout(getUserActivity(params), 30000, 'User Activity timed out'),
      withTimeout(getDashboardPerformance(params), 30000, 'Dashboard Performance timed out'),
      withTimeout(getWebSocketPerformance(params), 30000, 'WebSocket Performance timed out'),
      withTimeout(getApiPerformance(params), 30000, 'API Performance timed out'),
      withTimeout(getBrowserAnalytics(params), 30000, 'Browser Analytics timed out'),
    ]);

    results.forEach((result, index) => {
      const metricName = metricNames[index];
      if (result.status === 'rejected') {
        const errorMsg = `${metricName}: ${result.reason?.message || 'Unknown error'}`;
        metricsErrors.value.push(errorMsg);
        console.warn(`[ANALYTICS] ${errorMsg}`);
        switch (index) {
          case 0: coreWebVitalsData.value = null; break;
          case 1: pagePerformanceData.value = null; break;
          case 2: errorMetricsData.value = null; break;
          case 3: userActivityData.value = null; break;
          case 4: dashboardPerformanceData.value = null; break;
          case 5: webSocketPerformanceData.value = null; break;
          case 6: apiPerformanceData.value = null; break;
          case 7: browserAnalyticsData.value = null; break;
        }
      } else {
        switch (index) {
          case 0: coreWebVitalsData.value = result.value as CoreWebVitalsData; break;
          case 1: pagePerformanceData.value = result.value as PagePerformanceData; break;
          case 2: errorMetricsData.value = result.value as ErrorMetricsData; break;
          case 3: userActivityData.value = result.value as UserActivityData; break;
          case 4: dashboardPerformanceData.value = result.value as DashboardPerformanceData; break;
          case 5: webSocketPerformanceData.value = result.value as WebSocketPerformanceData; break;
          case 6: apiPerformanceData.value = result.value as ApiPerformanceData; break;
          case 7: browserAnalyticsData.value = result.value as BrowserAnalyticsData; break;
        }
      }
    });

    const successCount = results.filter(r => r.status === 'fulfilled').length;
    const failCount = results.filter(r => r.status === 'rejected').length;

    if (failCount === 0) {
      // All metrics loaded successfully
      notify.success('Analytics loaded successfully');
    } else if (failCount === 8) {
      // Total failure
      notify.error('Failed to load analytics metrics', 'Faro backend may be unavailable. Try refreshing later.');
    }

    console.log('[ANALYTICS] Loaded Faro metrics:', {
      successCount,
      failCount,
      coreWebVitals: coreWebVitalsData.value,
      pagePerformance: pagePerformanceData.value,
      errorMetrics: errorMetricsData.value,
      userActivity: userActivityData.value,
      dashboardPerformance: dashboardPerformanceData.value,
      webSocketPerformance: webSocketPerformanceData.value,
      apiPerformance: apiPerformanceData.value,
      browserAnalytics: browserAnalyticsData.value,
    });
  } catch (error) {
    console.error('[ANALYTICS] Error loading Faro metrics:', error);
    notify.error('Unexpected error loading analytics', error instanceof Error ? error.message : 'Unknown error');
  } finally {
    newMetricsLoading.value = false;
  }
};

/**
 * Range-key cache for Faro metrics lazy-load. Tracks the last range/filter
 * combination we actually fetched for, so when watchers fire on unrelated
 * tabs (auth/api) or on no-op re-applications of the same filter, we don't
 * hammer Loki with a fresh round of 5+ queries every time.
 *
 * Pair with `maybeLoadFaroMetrics()` below — together they collapse the
 * old "every watcher fires loadNewMetrics() unconditionally" pattern into
 * "only load when we're on the logs tab AND the range actually changed".
 */
const faroLoadedForRange = ref<string | null>(null);

const computeFaroRangeKey = (): string => {
  // Faro RUM queries take ONLY `timeRange` (see loadNewMetrics() params
  // and the 8 service functions). selectedSeverities / selectedServices
  // filter the *log* widgets above, not the RUM/Faro widgets. Including
  // them here would force a spurious re-fetch every time the user toggles
  // a severity chip — same LogQL, same response, just wasted work.
  return [
    selectedTimePreset.value,
    customStartDate.value || '',
    customEndDate.value || '',
  ].join('|');
};

const maybeLoadFaroMetrics = (): void => {
  // RUM widgets only render inside the `logs` tab. Switching to auth/api
  // and changing a filter must not trigger Faro calls the user can't see.
  if (activeTab.value !== 'logs') return;

  const key = computeFaroRangeKey();
  if (faroLoadedForRange.value === key) return;
  faroLoadedForRange.value = key;

  void loadNewMetrics();
};

/**
 * Load Auth Security Metrics
 * Uses Promise.allSettled for resilient loading
 */
const loadAuthMetrics = async () => {
  authMetricsLoading.value = true;
  authMetricsError.value = null;

  try {
    const params = { time_period: authTimePeriod.value };

    console.log('[AUTH METRICS] Loading metrics:', params);

    // Load both endpoints in parallel
    const results = await Promise.allSettled([
      authAnalyticsService.getAuthMetrics(params),
      authAnalyticsService.getIpAttacks(params),
    ]);

    // Handle metrics endpoint
    let metricsErrorDetail = '';
    if (results[0].status === 'fulfilled') {
      authMetricsData.value = results[0].value;
      console.log('[AUTH METRICS] Metrics loaded successfully:', results[0].value);
    } else {
      console.error('[AUTH METRICS] Failed to load metrics:', results[0].reason);
      authMetricsData.value = null;

      // Extract detailed error information
      const error = results[0].reason;
      if (error?.response?.status === 500) {
        metricsErrorDetail = 'Backend error (500) - Auth metrics endpoint not implemented or has bugs';
      } else if (error?.response?.status === 404) {
        metricsErrorDetail = 'Endpoint not found (404) - Auth metrics API not deployed';
      } else if (error?.response?.status === 401) {
        metricsErrorDetail = 'Unauthorized (401) - Authentication token invalid';
      } else if (error?.response?.status === 403) {
        metricsErrorDetail = 'Forbidden (403) - Admin permissions required';
      } else {
        metricsErrorDetail = `Network error - ${error?.message || 'Unknown error'}`;
      }
    }

    // Handle IP attacks endpoint
    let ipAttacksErrorDetail = '';
    if (results[1].status === 'fulfilled') {
      authIpAttacksData.value = results[1].value;
      console.log('[AUTH METRICS] IP attacks loaded successfully:', results[1].value);
    } else {
      console.error('[AUTH METRICS] Failed to load IP attacks:', results[1].reason);
      authIpAttacksData.value = null;

      // Extract detailed error information
      const error = results[1].reason;
      if (error?.response?.status === 500) {
        ipAttacksErrorDetail = 'Backend error (500) - IP attacks endpoint not implemented or has bugs';
      } else if (error?.response?.status === 404) {
        ipAttacksErrorDetail = 'Endpoint not found (404) - IP attacks API not deployed';
      } else if (error?.response?.status === 401) {
        ipAttacksErrorDetail = 'Unauthorized (401) - Authentication token invalid';
      } else if (error?.response?.status === 403) {
        ipAttacksErrorDetail = 'Forbidden (403) - Admin permissions required';
      } else {
        ipAttacksErrorDetail = `Network error - ${error?.message || 'Unknown error'}`;
      }
    }

    // Check if both failed
    if (results[0].status === 'rejected' && results[1].status === 'rejected') {
      // Build detailed error message
      const errorMessages = [];
      if (metricsErrorDetail) errorMessages.push(`Metrics: ${metricsErrorDetail}`);
      if (ipAttacksErrorDetail) errorMessages.push(`IP Attacks: ${ipAttacksErrorDetail}`);

      authMetricsError.value = errorMessages.length > 0
        ? errorMessages.join(' | ')
        : 'Failed to load auth metrics. Please try again.';

      notify.error('Failed to load auth metrics', authMetricsError.value);
    } else if (results[0].status === 'fulfilled' || results[1].status === 'fulfilled') {
      // At least one succeeded
      notify.success('Auth metrics loaded successfully');
    }

  } catch (error) {
    console.error('[AUTH METRICS] Unexpected error:', error);
    authMetricsError.value = 'Unexpected error loading auth metrics';

    notify.error('Error loading auth metrics', error instanceof Error ? error.message : 'Unknown error');
  } finally {
    authMetricsLoading.value = false;
  }
};

const calculateTrends = (logs: any[]) => {
  if (logs.length === 0) {
    logStats.value.topSource = { name: '-', count: 0 };
    logStats.value.peakTime = { time: '-', count: 0 };
    return;
  }

  // 1. Top Source
  const sourceCounts: Record<string, number> = {};
  logs.forEach(log => {
    const source = log.module || log.service || 'System';
    sourceCounts[source] = (sourceCounts[source] || 0) + 1;
  });

  let topSource = '-';
  let maxSourceCount = 0;

  Object.entries(sourceCounts).forEach(([source, count]) => {
    if (count > maxSourceCount) {
      maxSourceCount = count;
      topSource = source;
    }
  });

  logStats.value.topSource = { name: topSource, count: maxSourceCount };

  // 2. Peak Time (Hourly buckets)
  const timeCounts: Record<string, number> = {};
  logs.forEach(log => {
    // Group by hour: "YYYY-MM-DD HH:00"
    const date = new Date(log.timestamp);
    const key = `${date.getHours()}:00`;
    timeCounts[key] = (timeCounts[key] || 0) + 1;
  });

  let peakTime = '-';
  let maxTimeCount = 0;

  Object.entries(timeCounts).forEach(([time, count]) => {
    if (count > maxTimeCount) {
      maxTimeCount = count;
      peakTime = time;
    }
  });

  logStats.value.peakTime = { time: peakTime, count: maxTimeCount };
};

