// Get color for a service, with fallback to a generated color
const getServiceColor = (service: string, index: number): string => {
  const normalizedService = service.toLowerCase();
  for (const [key, color] of Object.entries(serviceColors)) {
    if (normalizedService.includes(key)) return color;
  }
  // Fallback to color from a palette based on index
  const fallbackColors = ['#64748b', '#a855f7', '#22c55e', '#0ea5e9', '#f43f5e', '#84cc16'];
  return fallbackColors[index % fallbackColors.length];
};

