// Helper: Get color based on success rate
const getSuccessRateColor = (rate: number): string => {
  if (rate >= 95) return 'positive';  // Green
  if (rate >= 85) return 'warning';   // Yellow
  return 'negative';                   // Red
};

// Helper: Get badge color for failed attempts
const getAttemptsBadgeColor = (attempts: number): string => {
  if (attempts >= 10) return 'negative';   // Red
  if (attempts >= 5) return 'warning';     // Yellow
  return 'info';                           // Blue
};

// Helper: Format datetime
const formatDateTime = (isoString: string): string => {
  try {
    const date = new Date(isoString);
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch (e) {
    return isoString;
  }
};

// Helper: Scroll to IP table
const ipTableRef = ref<HTMLElement | null>(null);
const scrollToIpTable = () => {
  ipTableRef.value?.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

/**
 * Handle tab change event
 */
const onTabChange = (tabName: 'logs' | 'auth' | 'api') => {
  console.log('[ANALYTICS] Tab changed to:', tabName);

  // Lazy load data for each tab on first access
  if (tabName === 'auth' && !authMetricsData.value) {
    loadAuthMetrics();
  }
  if (tabName === 'logs') {
    // Faro RUM widgets live on this tab. The gate inside
    // maybeLoadFaroMetrics() makes this a no-op when the same range was
    // already loaded (e.g. user switches auth→logs→auth→logs without
    // changing filters), so there's no double-fetch risk.
    maybeLoadFaroMetrics();
  }
  // Note: API Metrics tab handles its own data loading on component mount

  updateUrlParams();
};

// Watchers
watch(authTimePeriod, () => {
  if (activeTab.value === 'auth') {
    loadAuthMetrics();
    updateUrlParams();
  }
});

watch(selectedTimePreset, () => {
  loadMetrics();
  loadTimelineData();
  loadServiceData();
  maybeLoadFaroMetrics();
  updateUrlParams();
});

watch(selectedSeverities, () => {
  loadMetrics();
  loadTimelineData();
  loadServiceData();
  maybeLoadFaroMetrics();
  updateUrlParams();
});

watch(selectedServices, () => {
  loadMetrics();
  loadTimelineData();
  loadServiceData();
  maybeLoadFaroMetrics();
  updateUrlParams();
});

watch([customStartDate, customEndDate], () => {
  if (selectedTimePreset.value === 'custom' && customStartDate.value && customEndDate.value) {
    loadMetrics();
    loadTimelineData();
    loadServiceData();
    maybeLoadFaroMetrics();
    updateUrlParams();
  }
});

// Lifecycle
onMounted(() => {
  loadFromUrlParams();
  loadAvailableServices();

  // Load metrics based on active tab
  if (activeTab.value === 'auth') {
    loadAuthMetrics();
  } else if (activeTab.value === 'api') {
    // API Metrics tab handles its own data loading
  } else {
    loadMetrics();
    loadTimelineData();
    loadServiceData();
    maybeLoadFaroMetrics();
  }
});
