/**
 * Analytics Service
 *
 * Centralized service for all analytics API endpoints across 4 dashboards:
 * - Executive Dashboard (Business KPIs)
 * - Customer Success Dashboard (Health monitoring)
 * - Quality Dashboard (Validation metrics)
 * - Product Dashboard (Feature performance)
 *
 * Based on GitHub Issue #13900
 */

import AbstractApiService from 'src/services/abstractApiService';
import { DOC2API_URL } from 'src/pages/APIs';

// ============================================================================
// TypeScript Response Interfaces
// ============================================================================

// Common period interface used across all responses
interface PeriodInfo {
  start: string;
  end: string;
  period?: string;
  step?: string;
  hours?: number;
}

// ============================================================================
// Executive Dashboard Response Interfaces (5 endpoints)
// ============================================================================

export interface ExecutiveSummaryResponse {
  documents_processed: number;
  success_rate: number;
  growth_rate: number;
  estimated_revenue_cents: number;
  active_customers: number;
  period: PeriodInfo;
}

export interface VolumeTrendsResponse {
  timestamps: string[];
  values: number[];
  period: PeriodInfo;
}

export interface SuccessRatesResponse {
  timestamps: string[];
  values: number[];
  period: PeriodInfo;
}

export interface RevenueMetricsResponse {
  total_credits_consumed: number;
  estimated_cost_cents: number;
  avg_cost_per_document_cents: number;
  cost_by_doc_type: Record<string, number>;
  period: PeriodInfo;
}

export interface TopDocTypesResponse {
  top_doc_types: Array<{
    doc_type: string;
    count: number;
    percentage: number;
  }>;
  total_documents: number;
  period: PeriodInfo;
}

// ============================================================================
// Customer Success Dashboard Response Interfaces (5 endpoints)
// ============================================================================

export interface CustomerHealthResponse {
  health_score: number;
  health_category: 'excellent' | 'healthy' | 'at_risk' | 'critical';
  indicators: {
    document_volume: number;
    success_rate: number;
    sla_compliance: number;
    feature_adoption: number;
    user_engagement: number;
  };
  period: PeriodInfo;
}

export interface OrgPerformanceResponse {
  documents_processed: number;
  success_rate: number;
  avg_processing_time_seconds: number;
  error_rate: number;
  top_doc_types: string[];
  period: PeriodInfo;
}

export interface SlaComplianceResponse {
  overall_compliance_rate: number;
  documents_within_sla: number;
  documents_outside_sla: number;
  avg_processing_time_seconds: number;
  sla_threshold_seconds: number;
  period: PeriodInfo;
}

export interface FeatureAdoptionResponse {
  feature_usage: Array<{
    feature_name: string;
    usage_count: number;
    adoption_rate: number;
  }>;
  total_features_available: number;
  features_in_use: number;
  overall_adoption_rate: number;
  period: PeriodInfo;
}

export interface ActiveUsersResponse {
  active_users: number;
  total_sessions: number;
  avg_session_duration_seconds: number;
  engagement_level: 'low' | 'medium' | 'high';
  period: PeriodInfo;
}

// ============================================================================
// Quality Dashboard Response Interfaces (5 endpoints)
// ============================================================================

export interface ValidationErrorsResponse {
  errors_by_type: Record<string, number>;
  errors_by_severity: {
    critical: number;
    high: number;
    medium: number;
    low: number;
  };
  errors_by_field: Record<string, number>;
  total_errors: number;
  period: PeriodInfo;
  last_updated?: string | null;
  source?: 'database' | 'prometheus';
}

export interface ConfidenceDistributionResponse {
  distribution: Array<{
    bucket: string;
    count: number;
  }>;
  field_confidence: Record<string, number>;
  avg_confidence: number;
  min_confidence: number;
  max_confidence: number;
  period: PeriodInfo;
}

export interface ManualCorrectionsResponse {
  corrections_by_field: Record<string, number>;
  total_corrections: number;
  top_corrected_fields: Array<{
    field_name: string;
    count: number;
  }>;
  period: PeriodInfo;
  last_updated?: string | null;
  source?: 'database' | 'prometheus';
}

export interface ReviewQueueResponse {
  total_pending_review: number;
  by_reason: {
    low_confidence: number;
    validation_error: number;
    manual_flag: number;
  };
  timestamp: string;
}

export interface FieldPerformanceResponse {
  field_accuracy: Record<string, number>;
  low_accuracy_fields: Record<string, number>;
  avg_accuracy: number;
  total_fields: number;
  period: PeriodInfo;
  last_updated?: string | null;
  source?: 'database' | 'prometheus';
}

// New PostgreSQL-backed endpoints response interfaces
export interface WorstFieldsResponse {
  worst_fields: Array<{
    field_name: string;
    doc_type: string;
    accuracy: number; // 0-1 scale
    total_extractions: number;
  }>;
  period: PeriodInfo;
  last_updated: string | null;
}

export interface TrendsResponse {
  current_week: number | null; // 0-1 scale
  previous_week: number | null; // 0-1 scale
  trend: 'improving' | 'declining' | 'stable';
  change_percent: number | null; // 0-1 scale
  last_updated: string | null;
}

// ============================================================================
// Product Dashboard Response Interfaces (5 endpoints)
// ============================================================================

export interface ExtractionAccuracyResponse {
  accuracy_by_doc_type: Record<string, number>;
  overall_accuracy: number;
  total_extractions: number;
  successful_extractions: number;
  period: PeriodInfo;
}

export interface ProductFieldPerformanceResponse {
  field_performance: Array<{
    field_name: string;
    accuracy: number;
    extraction_count: number;
    avg_confidence: number;
  }>;
  total_fields_tracked: number;
  period: PeriodInfo;
}

export interface LanguageEffectivenessResponse {
  language_performance: Array<{
    language: string;
    document_count: number;
    avg_confidence: number;
    success_rate: number;
  }>;
  total_languages: number;
  period: PeriodInfo;
}

export interface FeatureUsageResponse {
  feature_usage: Array<{
    feature_name: string;
    usage_count: number;
    success_rate: number;
    avg_execution_time_ms: number;
  }>;
  total_features: number;
  period: PeriodInfo;
}

export interface ModulePerformanceResponse {
  module_performance: Array<{
    module_name: string;
    execution_count: number;
    success_rate: number;
    avg_duration_seconds: number;
    p95_duration_seconds: number;
  }>;
  total_modules: number;
  period: PeriodInfo;
}

// ============================================================================
// Analytics Service Class
// ============================================================================

export default class AnalyticsService extends AbstractApiService {
  public constructor() {
    super({});
  }

  // ==========================================================================
  // Executive Dashboard API Methods (5 methods)
  // ==========================================================================

  /**
   * Get executive summary with overall KPIs
   * @param period - Time period (24h|7d|30d|week|month|quarter) - default: 30d
   */
  public async getExecutiveSummary(
    period: string = '30d'
  ): Promise<ExecutiveSummaryResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/executive/summary?period=${period}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get document processing volume trends over time
   * @param period - Time period (24h|7d|30d|week|month|quarter) - default: 7d
   * @param step - Data point interval (1h|6h|1d) - default: 1h
   */
  public async getVolumeTrends(
    period: string = '7d',
    step: string = '1h'
  ): Promise<VolumeTrendsResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/executive/volume-trends?period=${period}&step=${step}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get success rate trends over time
   * @param period - Time period - default: 7d
   * @param step - Data point interval - default: 1h
   */
  public async getSuccessRates(
    period: string = '7d',
    step: string = '1h'
  ): Promise<SuccessRatesResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/executive/success-rates?period=${period}&step=${step}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get revenue metrics including credit consumption and costs
   * @param period - Time period - default: month
   */
  public async getRevenueMetrics(
    period: string = 'month'
  ): Promise<RevenueMetricsResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/executive/revenue-metrics?period=${period}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get top N document types by processing volume
   * @param period - Time period - default: 30d
   * @param topN - Number of results (1-50) - default: 10
   */
  public async getTopDocTypes(
    period: string = '30d',
    topN: number = 10
  ): Promise<TopDocTypesResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/executive/top-doc-types?period=${period}&top_n=${topN}`;
    return await this.getWithoutOrgId(endpoint);
  }

  // ==========================================================================
  // Customer Success Dashboard API Methods (5 methods)
  // ==========================================================================

  /**
   * Get customer health score for the authenticated organization
   * @param hours - Hours to look back (1-720) - default: 168 (7 days)
   */
  public async getCustomerHealth(
    hours: number = 168
  ): Promise<CustomerHealthResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/customer-success/health?hours=${hours}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get detailed performance metrics for the organization
   * @param hours - Hours to look back - default: 168
   */
  public async getOrgPerformance(
    hours: number = 168
  ): Promise<OrgPerformanceResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/customer-success/org-performance?hours=${hours}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get SLA compliance metrics
   * @param hours - Hours to look back - default: 168
   */
  public async getSlaCompliance(
    hours: number = 168
  ): Promise<SlaComplianceResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/customer-success/sla-compliance?hours=${hours}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get feature adoption metrics
   * @param hours - Hours to look back - default: 168
   * @param topN - Number of features to return - default: 10
   */
  public async getFeatureAdoption(
    hours: number = 168,
    topN: number = 10
  ): Promise<FeatureAdoptionResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/customer-success/feature-adoption?hours=${hours}&top_n=${topN}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get active user counts
   * @param hours - Hours to look back (1-720) - default: 24
   */
  public async getActiveUsers(
    hours: number = 24
  ): Promise<ActiveUsersResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/customer-success/active-users?hours=${hours}`;
    return await this.getWithoutOrgId(endpoint);
  }

  // ==========================================================================
  // Quality Dashboard API Methods (5 methods)
  // ==========================================================================

  /**
   * Get validation error breakdown by type, severity, and field
   * @param hours - Hours to look back (1-168) - default: 24
   * @param useDatabase - Use PostgreSQL backend instead of Prometheus - optional
   */
  public async getValidationErrors(
    hours: number = 24,
    useDatabase?: boolean
  ): Promise<ValidationErrorsResponse> {
    let endpoint = `${DOC2API_URL}/api/analytics/quality/validation-errors?hours=${hours}`;
    if (useDatabase !== undefined) {
      endpoint += `&use_database=${useDatabase}`;
    }
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get confidence score distribution histogram
   * @param hours - Hours to look back - default: 24
   * @param bucketCount - Number of histogram buckets (5-20) - default: 10
   */
  public async getConfidenceDistribution(
    hours: number = 24,
    bucketCount: number = 10
  ): Promise<ConfidenceDistributionResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/quality/confidence-distribution?hours=${hours}&bucket_count=${bucketCount}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get manual correction rates by field
   * @param hours - Hours to look back - default: 24
   * @param useDatabase - Use PostgreSQL backend instead of Prometheus - optional
   */
  public async getManualCorrections(
    hours: number = 24,
    useDatabase?: boolean
  ): Promise<ManualCorrectionsResponse> {
    let endpoint = `${DOC2API_URL}/api/analytics/quality/manual-corrections?hours=${hours}`;
    if (useDatabase !== undefined) {
      endpoint += `&use_database=${useDatabase}`;
    }
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get count of documents requiring manual review
   */
  public async getReviewQueue(): Promise<ReviewQueueResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/quality/review-queue`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get field-level extraction quality metrics
   * @param hours - Hours to look back - default: 24
   * @param minAccuracy - Minimum accuracy threshold for filtering (0.0-1.0) - optional
   * @param useDatabase - Use PostgreSQL backend instead of Prometheus - optional
   */
  public async getFieldPerformance(
    hours: number = 24,
    minAccuracy?: number,
    useDatabase?: boolean
  ): Promise<FieldPerformanceResponse> {
    let endpoint = `${DOC2API_URL}/api/analytics/quality/field-performance?hours=${hours}`;
    if (minAccuracy !== undefined) {
      endpoint += `&min_accuracy=${minAccuracy}`;
    }
    if (useDatabase !== undefined) {
      endpoint += `&use_database=${useDatabase}`;
    }
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get top N worst-performing fields by extraction accuracy
   * @param hours - Hours to look back (1-2160, default 720 = 30 days)
   * @param limit - Number of fields to return (1-50, default 10)
   */
  public async getWorstFields(
    hours: number = 720,
    limit: number = 10
  ): Promise<WorstFieldsResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/quality/worst-fields?hours=${hours}&limit=${limit}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get week-over-week accuracy trend analysis
   */
  public async getTrends(): Promise<TrendsResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/quality/trends`;
    return await this.getWithoutOrgId(endpoint);
  }

  // ==========================================================================
  // Product Dashboard API Methods (5 methods)
  // ==========================================================================

  /**
   * Get extraction accuracy by document type
   * @param hours - Hours to look back (1-720) - default: 168
   */
  public async getExtractionAccuracy(
    hours: number = 168
  ): Promise<ExtractionAccuracyResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/product/extraction-accuracy?hours=${hours}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get field-level extraction performance
   * @param hours - Hours to look back - default: 168
   * @param topN - Number of fields to return (1-50) - default: 20
   */
  public async getProductFieldPerformance(
    hours: number = 168,
    topN: number = 20
  ): Promise<ProductFieldPerformanceResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/product/field-performance?hours=${hours}&top_n=${topN}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get language-specific processing effectiveness
   * @param hours - Hours to look back - default: 168
   */
  public async getLanguageEffectiveness(
    hours: number = 168
  ): Promise<LanguageEffectivenessResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/product/language-effectiveness?hours=${hours}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get feature usage patterns
   * @param hours - Hours to look back - default: 168
   * @param topN - Number of features to return (1-50) - default: 15
   */
  public async getFeatureUsage(
    hours: number = 168,
    topN: number = 15
  ): Promise<FeatureUsageResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/product/feature-usage?hours=${hours}&top_n=${topN}`;
    return await this.getWithoutOrgId(endpoint);
  }

  /**
   * Get processing module performance metrics
   * @param hours - Hours to look back - default: 168
   */
  public async getModulePerformance(
    hours: number = 168
  ): Promise<ModulePerformanceResponse> {
    const endpoint = `${DOC2API_URL}/api/analytics/product/module-performance?hours=${hours}`;
    return await this.getWithoutOrgId(endpoint);
  }
}
