/**
 * Parse a Loki log entry value emitted by the Faro OTEL pipeline.
 *
 * Each Loki entry value arrives as JSON with shape:
 *   { "body": "<logfmt-formatted key=value pairs>",
 *     "traceid": "<hex>", "spanid": "<hex>", ... }
 *
 * This helper flattens that into one key->value map:
 *   - copies string-valued top-level fields (traceid, spanid, etc.)
 *   - then parses the `body` logfmt and merges its key/value pairs in
 *
 * Used by both `ApiMetricsService.getSlowestRequestsWithTraces` and
 * `FaroMetricsService.getJsErrorsWithStacks`.
 */
export function parseLokiBody(raw: string): Record<string, string> {
  if (!raw) return {};
  let outer: Record<string, unknown> = {};
  try {
    outer = JSON.parse(raw) as Record<string, unknown>;
  } catch {
    outer = { body: raw };
  }
  const result: Record<string, string> = {};
  for (const [k, v] of Object.entries(outer)) {
    if (typeof v === 'string') result[k] = v;
  }
  const body = typeof outer.body === 'string' ? outer.body : '';
  const logfmtPair = /([\w.]+)\s*=\s*("(?:[^"\\]|\\.)*"|[^\s]+)/g;
  let match: RegExpExecArray | null;
  while ((match = logfmtPair.exec(body)) !== null) {
    let val = match[2];
    if (val.startsWith('"') && val.endsWith('"')) {
      val = val.slice(1, -1).replace(/\\"/g, '"').replace(/\\\\/g, '\\');
    }
    result[match[1]] = val;
  }
  return result;
}
