      </q-card>
    </div>

    <!-- Revenue Metrics -->
    <div class="q-pa-md">
      <q-card flat bordered>
        <q-card-section>
          <div class="text-h6 q-mb-md">Revenue Metrics</div>
          <div v-if="isLoadingRevenue" class="text-center q-pa-xl">
            <q-spinner color="primary" size="48px" />
          </div>
          <div v-else class="row q-col-gutter-md">
            <div class="col-12 col-md-4">
              <div class="revenue-metric">
                <div class="text-subtitle2 text-grey-7">Total Credits Consumed</div>
                <div class="text-h5 text-weight-bold text-primary">
