            <div class="col-12 col-md-4">
              <div class="revenue-metric">
                <div class="text-subtitle2 text-grey-7">Avg Cost per Document</div>
                <div class="text-h5 text-weight-bold text-primary">
                  {{ formatCurrency(revenueMetrics.avg_cost_per_document_cents) }}
