<script setup lang="ts">
import { ref, computed, onMounted } from 'vue';
import { useQuasar } from 'quasar';
import VueApexCharts from 'vue3-apexcharts';
import AnalyticsService, {
  type ExecutiveSummaryResponse,
  type VolumeTrendsResponse,
  type SuccessRatesResponse,
  type TopDocTypesResponse,
  type CustomerHealthResponse,
  type SlaComplianceResponse,
  type ActiveUsersResponse,
  type FeatureAdoptionResponse,
  type RevenueMetricsResponse,
} from 'src/services/analytics/AnalyticsService';

// ============================================================================
// Component Setup
// ============================================================================

const apexchart = VueApexCharts;
const $q = useQuasar();
const analyticsService = new AnalyticsService();

// ============================================================================
// State
// ============================================================================

// Time filter
const selectedPeriod = ref('30d');
const periodOptions = [
  { label: 'Last 24 Hours', value: '24h' },
  { label: 'Last 7 Days', value: '7d' },
  { label: 'Last 30 Days', value: '30d' },
  { label: 'This Month', value: 'month' },
  { label: 'This Quarter', value: 'quarter' },
];

// Loading states
const isLoading = ref(false);
const isLoadingSummary = ref(false);
const isLoadingVolume = ref(false);
const isLoadingSuccessRate = ref(false);
const isLoadingDocTypes = ref(false);
const isLoadingHealth = ref(false);
const isLoadingRevenue = ref(false);

// Data
const executiveSummary = ref<ExecutiveSummaryResponse>({
  documents_processed: 0,
  success_rate: 0,
  growth_rate: 0,
  estimated_revenue_cents: 0,
  active_customers: 0,
  period: { start: '', end: '' },
});

const volumeTrends = ref<VolumeTrendsResponse>({
  timestamps: [],
  values: [],
  period: { start: '', end: '' },
});

const successRates = ref<SuccessRatesResponse>({
  timestamps: [],
  values: [],
  period: { start: '', end: '' },
});

const topDocTypes = ref<TopDocTypesResponse>({
  top_doc_types: [],
  total_documents: 0,
  period: { start: '', end: '' },
});

const customerHealth = ref<CustomerHealthResponse>({
  health_score: 0,
  health_category: 'healthy',
  indicators: {
    document_volume: 0,
    success_rate: 0,
    sla_compliance: 0,
    feature_adoption: 0,
    user_engagement: 0,
  },
  period: { start: '', end: '' },
});

const slaCompliance = ref<SlaComplianceResponse>({
  overall_compliance_rate: 0,
  documents_within_sla: 0,
  documents_outside_sla: 0,
  avg_processing_time_seconds: 0,
  sla_threshold_seconds: 0,
  period: { start: '', end: '' },
});

const activeUsers = ref<ActiveUsersResponse>({
  active_users: 0,
  total_sessions: 0,
  avg_session_duration_seconds: 0,
  engagement_level: 'medium',
  period: { start: '', end: '' },
});

const featureAdoption = ref<FeatureAdoptionResponse>({
  feature_usage: [],
  total_features_available: 0,
  features_in_use: 0,
  overall_adoption_rate: 0,
  period: { start: '', end: '' },
});

const revenueMetrics = ref<RevenueMetricsResponse>({
  total_credits_consumed: 0,
  estimated_cost_cents: 0,
  avg_cost_per_document_cents: 0,
  cost_by_doc_type: {},
  period: { start: '', end: '' },
});

// ============================================================================
// Computed - Chart Data
// ============================================================================

const volumeSeries = computed(() => [
  {
    name: 'Documents',
    data: (volumeTrends.value.timestamps ?? []).map((ts, i) => ({
      x: new Date(ts).getTime(),
      y: volumeTrends.value.values[i] || 0,
    })),
  },
]);

const volumeChartOptions = computed(() => ({
  chart: {
    type: 'area' as const,
    toolbar: { show: false },
    background: 'transparent',
  },
  colors: ['#3b82f6'],
  stroke: { curve: 'smooth' as const, width: 2 },
  fill: {
    type: 'gradient',
    gradient: {
      shadeIntensity: 1,
      opacityFrom: 0.4,
      opacityTo: 0.1,
      stops: [0, 100],
    },
  },
  xaxis: {
    type: 'datetime' as const,
    labels: {
      datetimeUTC: false,
      style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' },
    },
  },
  yaxis: {
    title: { text: 'Documents', style: { color: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
    labels: { style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
  },
  tooltip: {
    theme: $q.dark.isActive ? 'dark' : 'light',
    x: { format: 'MMM dd, HH:mm' },
  },
  grid: {
    borderColor: $q.dark.isActive ? '#374151' : '#e5e7eb',
  },
}));

const successRateSeries = computed(() => [
  {
    name: 'Success Rate (%)',
    data: (successRates.value.timestamps ?? []).map((ts, i) => ({
      x: new Date(ts).getTime(),
      y: successRates.value.values[i] || 0,
    })),
  },
]);

const successRateChartOptions = computed(() => ({
  chart: {
    type: 'line' as const,
    toolbar: { show: false },
    background: 'transparent',
  },
  colors: ['#10b981'],
  stroke: { width: 2, curve: 'smooth' as const },
  xaxis: {
    type: 'datetime' as const,
    labels: {
      datetimeUTC: false,
      style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' },
    },
  },
  yaxis: {
    title: { text: 'Success Rate (%)', style: { color: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
    labels: { style: { colors: $q.dark.isActive ? '#9ca3af' : '#6b7280' } },
    min: 0,
    max: 100,
  },
  tooltip: {
    theme: $q.dark.isActive ? 'dark' : 'light',
    y: { formatter: (val: number) => `${val.toFixed(1)}%` },
  },
  grid: {
    borderColor: $q.dark.isActive ? '#374151' : '#e5e7eb',
  },
}));

const docTypesSeries = computed(() =>
  (topDocTypes.value.top_doc_types ?? []).map((dt) => dt.count)
);

const docTypesChartOptions = computed(() => ({
  chart: {
    type: 'donut' as const,
    background: 'transparent',
  },
  colors: ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#14b8a6', '#f97316'],
  labels: (topDocTypes.value.top_doc_types ?? []).map((dt) => dt.doc_type),
  legend: {
    position: 'bottom' as const,
    labels: { colors: $q.dark.isActive ? '#9ca3af' : '#374151' },
  },
  plotOptions: {
    pie: {
      donut: {
        size: '65%',
        labels: {
          show: true,
          total: {
            show: true,
            label: 'Total',
            color: $q.dark.isActive ? '#9ca3af' : '#374151',
            formatter: () => formatNumber(topDocTypes.value.total_documents),
          },
        },
      },
    },
  },
  tooltip: {
    theme: $q.dark.isActive ? 'dark' : 'light',
    y: {
      formatter: (val: number, opts: { seriesIndex: number }) => {
        const docType = topDocTypes.value.top_doc_types[opts.seriesIndex];
        return `${val} (${docType?.percentage.toFixed(1) || 0}%)`;
      },
    },
  },
}));

// ============================================================================
// Helper Functions
// ============================================================================

function getPeriodLabel(): string {
  const option = periodOptions.find((o) => o.value === selectedPeriod.value);
  return option?.label || 'Last 30 Days';
}

function formatNumber(num: number): string {
  if (num == null) return '0';
  if (num >= 1000000) {
    return `${(num / 1000000).toFixed(1)}M`;
  }
  if (num >= 1000) {
    return `${(num / 1000).toFixed(1)}K`;
  }
  return num.toLocaleString();
}

function formatCurrency(cents: number): string {
  const euros = cents / 100;
  return new Intl.NumberFormat('de-DE', {
    style: 'currency',
    currency: 'EUR',
  }).format(euros);
}

function getSuccessRateColor(rate: number): string {
  if (rate >= 95) return 'positive';
  if (rate >= 85) return 'warning';
  return 'negative';
}

function getSuccessRateTextClass(rate: number): string {
  if (rate >= 95) return 'text-positive';
  if (rate >= 85) return 'text-warning';
  return 'text-negative';
}

function getHealthColor(category: string): string {
  switch (category) {
    case 'excellent':
      return 'positive';
    case 'healthy':
      return 'primary';
    case 'at_risk':
      return 'warning';
    case 'critical':
      return 'negative';
    default:
      return 'grey';
  }
}

function formatHealthCategory(category: string): string {
  if (!category) return '';
  return category
    .split('_')
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
}

// ============================================================================
// Data Loading Functions
// ============================================================================

async function loadExecutiveSummary() {
  isLoadingSummary.value = true;
  try {
    executiveSummary.value = await analyticsService.getExecutiveSummary(selectedPeriod.value);
  } catch (error) {
    console.error('[ExecutiveDashboard] Failed to load executive summary:', error);
  } finally {
    isLoadingSummary.value = false;
  }
}

async function loadVolumeTrends() {
  isLoadingVolume.value = true;
  try {
    const step = selectedPeriod.value === '24h' ? '1h' : selectedPeriod.value === '7d' ? '6h' : '1d';
    volumeTrends.value = await analyticsService.getVolumeTrends(selectedPeriod.value, step);
  } catch (error) {
    console.error('[ExecutiveDashboard] Failed to load volume trends:', error);
    volumeTrends.value = { timestamps: [], values: [], period: { start: '', end: '' } };
  } finally {
    isLoadingVolume.value = false;
  }
}

async function loadSuccessRates() {
  isLoadingSuccessRate.value = true;
  try {
    const step = selectedPeriod.value === '24h' ? '1h' : selectedPeriod.value === '7d' ? '6h' : '1d';
    successRates.value = await analyticsService.getSuccessRates(selectedPeriod.value, step);
  } catch (error) {
    console.error('[ExecutiveDashboard] Failed to load success rates:', error);
    successRates.value = { timestamps: [], values: [], period: { start: '', end: '' } };
  } finally {
    isLoadingSuccessRate.value = false;
  }
}

async function loadTopDocTypes() {
  isLoadingDocTypes.value = true;
  try {
    topDocTypes.value = await analyticsService.getTopDocTypes(selectedPeriod.value, 8);
  } catch (error) {
    console.error('[ExecutiveDashboard] Failed to load top doc types:', error);
    topDocTypes.value = { top_doc_types: [], total_documents: 0, period: { start: '', end: '' } };
  } finally {
    isLoadingDocTypes.value = false;
  }
}

async function loadCustomerHealthData() {
  isLoadingHealth.value = true;
  try {
    const hours = getHoursFromPeriod(selectedPeriod.value);
    const [health, sla, users, features] = await Promise.allSettled([
      analyticsService.getCustomerHealth(hours),
      analyticsService.getSlaCompliance(hours),
      analyticsService.getActiveUsers(hours),
      analyticsService.getFeatureAdoption(hours),
    ]);

    if (health.status === 'fulfilled') customerHealth.value = health.value;
    if (sla.status === 'fulfilled') slaCompliance.value = sla.value;
    if (users.status === 'fulfilled') activeUsers.value = users.value;
    if (features.status === 'fulfilled') featureAdoption.value = features.value;
  } catch (error) {
    console.error('[ExecutiveDashboard] Failed to load customer health data:', error);
  } finally {
    isLoadingHealth.value = false;
  }
}

async function loadRevenueMetrics() {
  isLoadingRevenue.value = true;
  try {
    revenueMetrics.value = await analyticsService.getRevenueMetrics(selectedPeriod.value);
  } catch (error) {
    console.error('[ExecutiveDashboard] Failed to load revenue metrics:', error);
  } finally {
    isLoadingRevenue.value = false;
  }
}

function getHoursFromPeriod(period: string): number {
  switch (period) {
    case '24h':
      return 24;
    case '7d':
      return 168;
    case '30d':
      return 720;
    case 'month':
      return 720;
    case 'quarter':
      return 2160;
    default:
      return 168;
  }
}

async function refreshAllData() {
  isLoading.value = true;
  await Promise.allSettled([
    loadExecutiveSummary(),
    loadVolumeTrends(),
    loadSuccessRates(),
    loadTopDocTypes(),
    loadCustomerHealthData(),
    loadRevenueMetrics(),
  ]);
  isLoading.value = false;
}

function onPeriodChange() {
  refreshAllData();
}

// ============================================================================
// Lifecycle
// ============================================================================

onMounted(() => {
  refreshAllData();
});
</script>

