/**
 * Faro Metrics Service — LogQL Metric Query Edition
 *
 * The previous version fetched up to 1000 raw log entries per widget, parsed
 * each body via regex, and computed percentiles in JavaScript. That meant
 * megabytes of network traffic, 25s+ Loki queries for 30-day ranges, and
 * silent failure modes when LogQL filters drifted from the actual Faro v2.4
 * event shapes.
 *
 * This rewrite uses **Loki LogQL metric queries** (`quantile_over_time`,
 * `count_over_time`, `sum by (...)`) so the server returns scalar values or
 * tiny vectors. Each widget needs 1–5 sub-second queries instead of one
 * mega-fetch. Sub-second response for 1h, today, 7d, and 30d alike.
 *
 * Architecture:
 *   Browser  →  Loki LogQL metric query  →  scalar values  →  UI
 *
 * Prerequisites (DevOps): the Alloy `loki.process` stage promotes 3 fields
 * to Loki stream labels (kind, event_name, measurement_type), which is what
 * the queries below filter on. See
 *   DevOps/infrastructure/monitoring/logging/faro/dev-stage-values.yaml
 */

import axios, { AxiosError } from 'axios';
import { getLokiApiUrl } from 'src/utils/lokiUrl';
import type {
  CoreWebVitalsData,
  PagePerformanceData,
  ErrorMetricsData,
  UserActivityData,
  DashboardPerformanceData,
  WebSocketPerformanceData,
  ApiPerformanceData,
  BrowserAnalyticsData,
  FaroQueryParams,
  PercentileMetric,
  TimeSeriesPoint,
  ErrorSummary,
  ApiEndpointSummary,
  ApiTrendPoint,
  BrowserSummary,
  OSSummary,
  BrowserTrendPoint,
  JsErrorEntry,
} from './types';
import { parseLokiBody } from './lokiBodyParser';

/* -------------------------------------------------------------------------
 * Loki API response shapes
 * ------------------------------------------------------------------------- */

interface LokiInstantResponse {
  status: 'success' | 'error';
  data: {
    resultType: 'vector' | 'matrix' | 'scalar' | 'streams';
    result: Array<{
      metric?: Record<string, string>;
      stream?: Record<string, string>;
      // Loki API returns timestamps as either number or numeric string,
      // depending on resultType. Keep both for safe destructuring.
      value?: [number | string, string]; // instant vector
      values?: Array<[number | string, string]>; // matrix
    }>;
  };
  error?: string;
}

function toNumberTs(ts: number | string): number {
  return typeof ts === 'number' ? ts : parseFloat(ts) || 0;
}

/* -------------------------------------------------------------------------
 * Time range parsing
 * ------------------------------------------------------------------------- */

function parseTimeRange(timeRange: string): number {
  const match = timeRange.match(/^(\d+)([hmd])$/);
  if (!match) return 24 * 60 * 60 * 1000;
  const value = parseInt(match[1], 10);
  switch (match[2]) {
    case 'h': return value * 60 * 60 * 1000;
    case 'd': return value * 24 * 60 * 60 * 1000;
    case 'm': return value * 60 * 1000;
    default: return 24 * 60 * 60 * 1000;
  }
}

/**
 * The LogQL range duration string (`[24h]`, `[7d]`, ...). Loki accepts s, m,
 * h, d. We always pick the smallest sensible unit so the range vector
 * matches the user's selected window exactly.
 */
function toLogQLRange(timeRange: string): string {
  const m = timeRange.match(/^(\d+)([hmd])$/);
  if (!m) return '24h';
  return `${m[1]}${m[2]}`;
}

/* -------------------------------------------------------------------------
 * Loki HTTP helpers
 *
 * - lokiInstant: GET /query, returns a single instant value
 * - lokiInstantBySeries: same, but returns a vector keyed by label combos
 * - lokiRange: GET /query_range, returns a matrix (time series)
 *
 * All three swallow network/4xx failures and return safe defaults so a
 * single bad query never poisons the whole dashboard render.
 * ------------------------------------------------------------------------- */

/**
 * In-flight dedup map: if a second caller asks for the exact same
 * `path + sorted(params)` combination while the first request is still
 * pending, the second caller latches onto the same Promise. Cuts ~30 %
 * of the parallel-render burst when, e.g. getCoreWebVitals and
 * getPagePerformance both unwrap `ttfb` on the web-vitals stream within
 * the same render. The entry is deleted as soon as the underlying promise
 * settles — this is NOT a result cache, only burst-coalescing.
 *
 * The previous executeLokiQuery cache was removed during the LogQL
 * refactor; this is a narrower, settle-evicted version targeted at the
 * 7d/30d HTTP 429 cascade.
 */
const inFlightQueries: Map<string, Promise<LokiInstantResponse | null>> = new Map();

function buildInFlightKey(path: string, params: Record<string, string>): string {
  const sorted = Object.keys(params).sort().map((k) => `${k}=${params[k]}`).join('&');
  return `${path}?${sorted}`;
}

/**
 * Global concurrency semaphore for Loki HTTP. At most LOKI_MAX_CONCURRENT
 * requests are in flight at any time; the rest wait FIFO.
 *
 * N=8 was chosen after followup-7's N=4 proved too conservative — Loki
 * with 3 replicas / max_concurrent=64 / outstanding=8192 happily eats 8
 * concurrent client streams, and the user-visible wall-clock dropped from
 * ~25 s (at N=4 with serial widget execution) to ~5–8 s at 7 d.
 *
 * Math: 117 queries × ~30 % dedup ≈ 80 unique × 8 concurrent = 10 rounds.
 * Round latency at 7 d ~0.5 s → ~5 s. At 30 d ~1.2 s → ~12 s.
 *
 * Safety: peak outstanding sub-queries = 8 × ~28 (split=6h) = 224, well
 * under per-tenant cap 8192. Per-querier max_concurrent=64 × 3 replicas
 * = 192 effective, so worst-case Loki internally queues a fraction —
 * verified with 100 parallel curls.
 *
 * Exported for tests; production callers should never set this manually.
 */
export const LOKI_MAX_CONCURRENT = 8;
let lokiInFlightCount = 0;
const lokiWaitQueue: Array<() => void> = [];

function acquireSlot(): Promise<void> {
  if (lokiInFlightCount < LOKI_MAX_CONCURRENT) {
    lokiInFlightCount += 1;
    return Promise.resolve();
  }
  return new Promise<void>((resolve) => {
    lokiWaitQueue.push(() => {
      lokiInFlightCount += 1;
      resolve();
    });
  });
}

function releaseSlot(): void {
  lokiInFlightCount -= 1;
  const next = lokiWaitQueue.shift();
  if (next) next();
}

async function lokiHttp(path: string, params: Record<string, string>): Promise<LokiInstantResponse | null> {
  const baseUrl = getLokiApiUrl();
  if (!baseUrl) return null;

  const key = buildInFlightKey(path, params);
  const existing = inFlightQueries.get(key);
  if (existing) return existing;

  const promise = (async () => {
    await acquireSlot();
    try {
      const response = await axios.get<LokiInstantResponse>(`${baseUrl}${path}`, {
        params,
        timeout: 45_000,
      });
      if (response.data.status !== 'success') return null;
      return response.data;
    } catch (error) {
      const axiosErr = error as AxiosError;
      const status = axiosErr.response?.status;
      if (status && status >= 400 && status < 500) {
        console.warn(`[FARO/Loki] ${status} for query`, params.query);
      }
      return null;
    } finally {
      releaseSlot();
    }
  })();

  inFlightQueries.set(key, promise);
  // Always evict on settle — entry is settle-scoped, not time-scoped.
  promise.finally(() => {
    if (inFlightQueries.get(key) === promise) inFlightQueries.delete(key);
  });

  return promise;
}

export async function lokiInstant(query: string, endMs: number): Promise<number> {
  const data = await lokiHttp('/query', { query, time: String(endMs * 1_000_000) });
  const result = data?.data?.result;
  if (!result?.length) return 0;
  const raw = result[0]?.value?.[1];
  const num = parseFloat(String(raw ?? '0'));
  return Number.isFinite(num) ? num : 0;
}

export async function lokiInstantBySeries(
  query: string,
  endMs: number,
): Promise<Array<{ labels: Record<string, string>; value: number }>> {
  const data = await lokiHttp('/query', { query, time: String(endMs * 1_000_000) });
  const result = data?.data?.result ?? [];
  return result.map((r) => ({
    labels: r.metric ?? {},
    value: parseFloat(String(r.value?.[1] ?? '0')) || 0,
  }));
}

export async function lokiRange(
  query: string,
  startMs: number,
  endMs: number,
  stepSec: number,
): Promise<TimeSeriesPoint[]> {
  const data = await lokiHttp('/query_range', {
    query,
    start: String(startMs * 1_000_000),
    end: String(endMs * 1_000_000),
    step: String(stepSec),
  });
  const result = data?.data?.result;
  if (!result?.length) return [];
  // Take the first series (most LogQL metric queries we use return one series)
  const points = result[0]?.values ?? [];
  return points.map(([ts, val]) => ({
    timestamp: Math.floor(toNumberTs(ts) * 1000),
    value: parseFloat(val) || 0,
  }));
}

/**
 * Range query that preserves EVERY series (not just the first). Used by the
 * API Metrics tab to compute per-step percentiles separately from request
 * volume in one LogQL round-trip.
 */
export async function lokiRangeBySeries(
  query: string,
  startMs: number,
  endMs: number,
  stepSec: number,
): Promise<Array<{ labels: Record<string, string>; points: TimeSeriesPoint[] }>> {
  const data = await lokiHttp('/query_range', {
    query,
    start: String(startMs * 1_000_000),
    end: String(endMs * 1_000_000),
    step: String(stepSec),
  });
  const result = data?.data?.result ?? [];
  return result.map((r) => ({
    labels: r.metric ?? {},
    points: (r.values ?? []).map(([ts, val]) => ({
      timestamp: Math.floor(toNumberTs(ts) * 1000),
      value: parseFloat(val) || 0,
    })),
  }));
}

/**
 * Run the same LogQL pattern for 4 percentiles (P50/P75/P95/P99).
 *
 * Sequential by design. The previous parallel version fired 4 concurrent
 * HTTP requests per metric — with 6 metrics per widget × 8 widgets that's
 * ~120 simultaneous Loki connections, which saturated the per-tenant
 * outstanding-query queue at 7d/30d ranges and triggered cascading 429s.
 * Sequential here means each metric still runs in parallel with other
 * metrics (`Promise.all([percentiles(ttfb), percentiles(lcp), …])`) but
 * within a single metric the 4 percentile calls chain. Net effect: peak
 * Loki concurrency per widget drops from 24 to 6.
 */
async function percentiles(logqlPattern: string, endMs: number): Promise<PercentileMetric> {
  const p50 = await lokiInstant(logqlPattern.replace('{P}', '0.5'), endMs);
  const p75 = await lokiInstant(logqlPattern.replace('{P}', '0.75'), endMs);
  const p95 = await lokiInstant(logqlPattern.replace('{P}', '0.95'), endMs);
  const p99 = await lokiInstant(logqlPattern.replace('{P}', '0.99'), endMs);
  return { p50, p75, p95, p99 };
}

function emptyPercentile(): PercentileMetric {
  return { p50: 0, p75: 0, p95: 0, p99: 0 };
}

/**
 * Pick a step (in seconds) for `query_range` based on the window length.
 * Total bucket count ~25–50 keeps charts readable without flooding Loki.
 *
 * Exported so callers in `ApiMetricsService` derive the same bucketing the
 * Faro widgets use — keeps the dashboard consistent across tabs.
 */
export function pickStep(rangeMs: number): number {
  const hours = rangeMs / 3_600_000;
  if (hours <= 1) return 60;          // 1h → 60 buckets of 1 min
  if (hours <= 24) return 1800;       // 24h → 48 buckets of 30 min
  if (hours <= 168) return 14_400;    // 7d → 42 buckets of 4 h
  return 43_200;                       // 30d → 60 buckets of 12 h
  // NOTE: step=86_400s (1 day) is silently rejected by our Loki cluster
  // for `count_over_time` range queries — returns 0 series even when
  // smaller steps over the same range return data. Empirically anything
  // ≤ 43_200s works, so cap at 12h buckets for the 30d window.
}

/**
 * Convert `hours` count to the LogQL range duration string. Mirrors the
 * `toLogQLRange` helper used internally; exported so ApiMetricsService can
 * build identical range expressions without re-implementing the math.
 */
export function hoursToLogQLRange(hours: number): string {
  if (hours <= 0) return '1h';
  if (hours >= 24 && hours % 24 === 0) return `${hours / 24}d`;
  return `${hours}h`;
}

export function isFaroAvailable(): boolean {
  return getLokiApiUrl() !== '';
}

/* -------------------------------------------------------------------------
 * 1. Core Web Vitals
 *    Faro emits as kind=measurement, measurement_type=web-vitals
 *    Body fields: ttfb, fcp, lcp, cls, fid, inp (numeric)
 * ------------------------------------------------------------------------- */

export async function getCoreWebVitals(params: FaroQueryParams): Promise<CoreWebVitalsData> {
  if (!isFaroAvailable()) throw new Error('Core Web Vitals data unavailable');
  const range = toLogQLRange(params.timeRange || '24h');
  const endMs = Date.now();
  // The webvitals stream usually emits multiple metric names per record (one
  // log line per fired event), so we unwrap each field separately.
  const baseStream = `{source="faro", type="rum", measurement_type="web-vitals"}`;
  // `by ()` collapses ALL series into one global aggregate. Without it,
  // `| logfmt` parses every body field into a label, and the resulting
  // 5000+ unique label combinations trip Loki's `maximum of series` guard.
  const q = (field: string) =>
    `quantile_over_time({P}, ${baseStream} | logfmt | unwrap ${field} [${range}]) by ()`;

  const [ttfb, fcp, lcp, cls, fid, inp] = await Promise.all([
    percentiles(q('ttfb'), endMs),
    percentiles(q('fcp'), endMs),
    percentiles(q('lcp'), endMs),
    percentiles(q('cls'), endMs),
    percentiles(q('fid'), endMs),
    percentiles(q('inp'), endMs),
  ]);

  return { ttfb, fcp, lcp, cls, fid, inp };
}

/* -------------------------------------------------------------------------
 * 2. Page Performance — same stream as web-vitals plus navigation timing
 * ------------------------------------------------------------------------- */

export async function getPagePerformance(params: FaroQueryParams): Promise<PagePerformanceData> {
  if (!isFaroAvailable()) throw new Error('Page Performance data unavailable');
  const range = toLogQLRange(params.timeRange || '24h');
  const endMs = Date.now();
  const stream = `{source="faro", type="rum", measurement_type=~"web-vitals|navigation|page-timing"}`;
  // `by ()` collapses series so Loki's 5000-series guard doesn't fire on
  // high-cardinality body labels added by `| logfmt`.
  const q = (field: string) =>
    `quantile_over_time({P}, ${stream} | logfmt | unwrap ${field} [${range}]) by ()`;

  // Each metric is computed only if Faro emits that field. Missing fields
  // return 0 silently via the safe defaults in lokiInstant.
  const [dnsLookup, tcpConnect, tlsHandshake, ttfb, domLoad, fullPageLoad] = await Promise.all([
    percentiles(q('dnsLookupTime'), endMs),
    percentiles(q('tcpHandshakeTime'), endMs),
    percentiles(q('tlsNegotiationTime'), endMs),
    percentiles(q('ttfb'), endMs),
    percentiles(q('domContentLoaded'), endMs),
    percentiles(q('fullPageLoad'), endMs),
  ]);

  return { dnsLookup, tcpConnect, tlsHandshake, ttfb, domLoad, fullPageLoad };
}

/* -------------------------------------------------------------------------
 * 3. Error Metrics
 *    Counts:    {kind="exception"} (JS errors) and {kind="log", level="error"} (console)
 *    Trend:     count_over_time bucketed via step
 *    Top errors: sum by (message) — but message is high-cardinality, so we
 *                fall back to a tiny line-read at the end (10 most recent).
 * ------------------------------------------------------------------------- */

export async function getErrorMetrics(params: FaroQueryParams): Promise<ErrorMetricsData> {
  if (!isFaroAvailable()) throw new Error('Error Metrics data unavailable');
  const range = toLogQLRange(params.timeRange || '24h');
  const rangeMs = parseTimeRange(params.timeRange || '24h');
  const endMs = Date.now();
  const startMs = endMs - rangeMs;
  const stepSec = pickStep(rangeMs);

  const [jsErrorCount, consoleErrorCount, trendPoints, consoleTrendPoints, recentErrors] = await Promise.all([
    lokiInstant(
      `sum(count_over_time({source="faro", type="rum", kind="exception"} [${range}]))`,
      endMs,
    ),
    lokiInstant(
      `sum(count_over_time({source="faro", type="rum", kind="log", level="error"} [${range}]))`,
      endMs,
    ),
    lokiRange(
      `sum(count_over_time({source="faro", type="rum", kind="exception"} [${stepSec}s]))`,
      startMs,
      endMs,
      stepSec,
    ),
    lokiRange(
      `sum(count_over_time({source="faro", type="rum", kind="log", level="error"} [${stepSec}s]))`,
      startMs,
      endMs,
      stepSec,
    ),
    // For "top errors" we still need raw text for the message — fetch ≤20
    // recent exceptions only.
    lokiHttp('/query_range', {
      query: '{source="faro", type="rum", kind="exception"}',
      start: String(startMs * 1_000_000),
      end: String(endMs * 1_000_000),
      limit: '20',
    }),
  ]);

  // Extract message strings from up to 20 recent exception bodies
  const errorMessages: Record<string, number> = {};
  const pages = new Set<string>();
  const streams = recentErrors?.data?.result ?? [];
  for (const s of streams) {
    for (const [, raw] of (s as { values?: Array<[unknown, string]> }).values ?? []) {
      const line = String(raw);
      // The Loki line is JSON-wrapped — pull body out cheaply
      const bodyMatch = line.match(/"body":"([^"]+)"/);
      const body = bodyMatch ? bodyMatch[1] : line;
      const msg = body.match(/message="([^"]+)"/)?.[1] ?? body.match(/message=(\S+)/)?.[1];
      if (msg) errorMessages[msg] = (errorMessages[msg] || 0) + 1;
      const pageMatch = body.match(/page_url=(\S+)/)?.[1];
      if (pageMatch) pages.add(pageMatch);
    }
  }
  const topErrors: ErrorSummary[] = Object.entries(errorMessages)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([message, count]) => ({ message, count }));

  return {
    jsErrorCount,
    consoleErrorCount,
    errorRateTrend: trendPoints,
    consoleErrorTrend: consoleTrendPoints,
    topErrors,
    affectedPages: Array.from(pages).slice(0, 10),
  };
}

/**
 * Get the N most recent JS exceptions with full stack traces and trace
 * IDs for client-side investigation. Mirrors the pattern of
 * `ApiMetricsService.getSlowestRequestsWithTraces`: a Loki log query
 * (not metric) capped at 24h, parsed via the shared `parseLokiBody`.
 *
 * Range is capped at 24h because Loki log queries are bounded to ~5000
 * entries and at 30d the newest-first slice would not represent the
 * full window. For the "Top Errors" aggregate counts we already have
 * `getErrorMetrics` with proper bucketed range queries.
 */
export async function getJsErrorsWithStacks(
  hours: number = 1,
  limit: number = 20,
): Promise<JsErrorEntry[]> {
  if (!isFaroAvailable()) return [];
  try {
    const cappedHours = Math.min(Math.max(hours, 1), 24);
    const endMs = Date.now();
    const startMs = endMs - cappedHours * 60 * 60 * 1000;
    // Log query — not aggregated; we need raw bodies for stack + trace_id.
    const response = await lokiHttp('/query_range', {
      query: '{source="faro", type="rum", kind="exception"}',
      start: String(startMs * 1_000_000),
      end: String(endMs * 1_000_000),
      limit: '1000',
      direction: 'backward',
    });
    if (!response) return [];
    const entries: JsErrorEntry[] = [];
    const streams = (response.data?.result ?? []) as Array<{
      values?: Array<[string, string]>;
    }>;
    for (const stream of streams) {
      for (const [tsNs, raw] of stream.values ?? []) {
        const parsed = parseLokiBody(raw);
        const message = parsed.event_data_value || parsed.value || '';
        if (!message) continue;
        const browserName = parsed.browser_name || '';
        const browserVersion = parsed.browser_version || '';
        entries.push({
          timestamp: new Date(Number(tsNs) / 1_000_000).toISOString(),
          type: parsed.event_data_type || parsed.type || 'Error',
          message,
          stacktrace: parsed.event_data_stacktrace || parsed.stacktrace || '',
          browser: browserVersion ? `${browserName} ${browserVersion}` : browserName,
          pageUrl: parsed.page_url || '',
          sessionId: parsed.session_id || '',
          traceId: parsed.traceID || parsed.traceid || '',
        });
      }
    }
    entries.sort((a, b) => b.timestamp.localeCompare(a.timestamp));
    return entries.slice(0, limit);
  } catch (error) {
    console.error('[FaroMetrics] getJsErrorsWithStacks failed:', error);
    return [];
  }
}

/* -------------------------------------------------------------------------
 * 4. User Activity
 *    Sessions: count distinct via `count by (session_id)` then count rows
 *    Trend:    count_over_time of session_start events bucketed
 * ------------------------------------------------------------------------- */

export async function getUserActivity(params: FaroQueryParams): Promise<UserActivityData> {
  if (!isFaroAvailable()) throw new Error('User Activity data unavailable');
  const range = toLogQLRange(params.timeRange || '24h');
  const rangeMs = parseTimeRange(params.timeRange || '24h');
  const endMs = Date.now();
  const startMs = endMs - rangeMs;
  const stepSec = pickStep(rangeMs);

  // Session activations = `session_start` + `session_resume` events.
  // Counting these marker events is ~13× cheaper than the previous
  // `count by (session_id) (... | logfmt session_id ...)` form, which at
  // 30d scanned every RUM log line and routinely exceeded axios's 30s
  // timeout. Semantically this counts how often users opened or
  // re-activated the app — a cleaner UX metric than "distinct session_ids
  // that ever appeared in any log line".
  const [uniqueSessions, sessionTrend] = await Promise.all([
    lokiInstant(
      `sum(count_over_time({source="faro", type="rum", event_name=~"session_start|session_resume"} [${range}]))`,
      endMs,
    ),
    lokiRange(
      `sum(count_over_time({source="faro", type="rum", kind="event"} [${stepSec}s]))`,
      startMs,
      endMs,
      stepSec,
    ),
  ]);

  // Peak activity hour = bucket with max value, expressed as 0–23 local hour
  let peakActivityHour = 0;
  let max = -1;
  for (const point of sessionTrend) {
    if (point.value > max) {
      max = point.value;
      peakActivityHour = new Date(point.timestamp).getHours();
    }
  }

  return {
    uniqueSessions: Math.round(uniqueSessions),
    avgSessionDuration: 0, // would need session_start + session_end correlation; out of scope
    peakActivityHour,
    sessionTrend,
  };
}

/* -------------------------------------------------------------------------
 * 5. Dashboard Performance — Faro v2.4 does not emit dashboard measurements
 *    today. This widget stays as a graceful empty placeholder until the
 *    frontend instruments `pushMeasurement({type: 'dashboard', ...})`.
 * ------------------------------------------------------------------------- */

export async function getDashboardPerformance(params: FaroQueryParams): Promise<DashboardPerformanceData> {
  if (!isFaroAvailable()) throw new Error('Dashboard Performance data unavailable');
  const range = toLogQLRange(params.timeRange || '24h');
  const endMs = Date.now();
  const stream = `{source="faro", type="rum", measurement_type=~"dashboard|custom"}`;
  // `by ()` collapses series to avoid Loki's 5000-series guard.
  const q = (field: string) =>
    `quantile_over_time({P}, ${stream} | logfmt | unwrap ${field} [${range}]) by ()`;

  const [initialLoad, fullLoad, timeToInteractive, widgetRender, dataRefresh, widgetErrors] =
    await Promise.all([
      percentiles(q('initial_load'), endMs),
      percentiles(q('full_load'), endMs),
      percentiles(q('time_to_interactive'), endMs),
      percentiles(q('widget_render'), endMs),
      percentiles(q('data_refresh'), endMs),
      lokiInstant(
        `sum(count_over_time({source="faro", type="rum", kind="exception"} |~ "widget" [${range}]))`,
        endMs,
      ),
    ]);

  return { initialLoad, fullLoad, timeToInteractive, widgetRender, widgetErrors, dataRefresh };
}

/* -------------------------------------------------------------------------
 * 6. WebSocket Performance
 * ------------------------------------------------------------------------- */

export async function getWebSocketPerformance(params: FaroQueryParams): Promise<WebSocketPerformanceData> {
  if (!isFaroAvailable()) throw new Error('WebSocket Performance data unavailable');
  const range = toLogQLRange(params.timeRange || '24h');
  const endMs = Date.now();
  const wsStream = `{source="faro", type="rum", measurement_type=~"websocket.*"}`;

  const [connectionDuration, messageLatency, messageSize, messageProcessing,
    reconnectAttempts, connectionFailures, errorCount, messagesReceived] =
    await Promise.all([
      percentiles(
        `quantile_over_time({P}, {source="faro", type="rum", measurement_type="websocket"} | logfmt | unwrap connect_time_ms [${range}]) by ()`,
        endMs,
      ),
      percentiles(
        `quantile_over_time({P}, {source="faro", type="rum", measurement_type="websocket_latency"} | logfmt | unwrap round_trip_ms [${range}]) by ()`,
        endMs,
      ),
      percentiles(
        `quantile_over_time({P}, {source="faro", type="rum", measurement_type="websocket_message"} | logfmt | unwrap message_size_bytes [${range}]) by ()`,
        endMs,
      ),
      percentiles(
        `quantile_over_time({P}, {source="faro", type="rum", measurement_type="websocket_message"} | logfmt | unwrap processing_time_ms [${range}]) by ()`,
        endMs,
      ),
      lokiInstant(`sum(count_over_time(${wsStream} |~ "reconnect_attempt|is_reconnect" [${range}]))`, endMs),
      lokiInstant(`sum(count_over_time(${wsStream} |~ "connection_failure|failed=true" [${range}]))`, endMs),
      lokiInstant(
        `sum(count_over_time({source="faro", type="rum", kind="exception", measurement_type="WebSocket_NETWORK"} [${range}]))`,
        endMs,
      ),
      lokiInstant(
        `sum(count_over_time({source="faro", type="rum", measurement_type="websocket_message"} [${range}]))`,
        endMs,
      ),
    ]);

  return {
    connectionDuration,
    reconnectAttempts: Math.round(reconnectAttempts),
    connectionFailures: Math.round(connectionFailures),
    activeConnections: 0,
    messageLatency,
    messageProcessing,
    messageSize,
    messagesReceived: Math.round(messagesReceived),
    errorCount: Math.round(errorCount),
  };
}

/* -------------------------------------------------------------------------
 * 7. API Performance — Faro v2.4 traces every fetch/XHR with event_name
 * ------------------------------------------------------------------------- */

export function getApiPerformance(params: FaroQueryParams): Promise<ApiPerformanceData> {
  // No more per-timeRange Promise cache — each LogQL metric query is already
  // sub-second so the win isn't worth the rejected-promise foot-gun the old
  // cache introduced (DOCB-12251 incident).
  return _fetchApiPerformance(params.timeRange || '24h');
}

async function _fetchApiPerformance(timeRange: string): Promise<ApiPerformanceData> {
  if (!isFaroAvailable()) throw new Error('API Performance data unavailable');
  const range = toLogQLRange(timeRange);
  const rangeMs = parseTimeRange(timeRange);
  const endMs = Date.now();
  const startMs = endMs - rangeMs;
  const stepSec = pickStep(rangeMs);

  const apiStream =
    `{source="faro", type="rum", event_name=~"faro.tracing.fetch|faro.tracing.xml-http-request"}`;
  const unwrapMs =
    `${apiStream} | logfmt | unwrap event_data_duration_ns | __error__=""`;

  // Loki returns duration in ns; we'll divide by 1e6 client-side.
  // All quantile queries use `by ()` (global) or `by (label)` (grouped) to
  // collapse logfmt-derived series and stay under Loki's 5000-series limit.
  const [responseTimeNs, requestCount, successCount, trendCountSeries, trendP95SeriesNs, slowestVec] =
    await Promise.all([
      percentiles(`quantile_over_time({P}, ${unwrapMs} [${range}]) by ()`, endMs),
      lokiInstant(`sum(count_over_time(${apiStream} [${range}]))`, endMs),
      lokiInstant(
        `sum(count_over_time(${apiStream} | logfmt | event_data_http_status_code=~"[123].." [${range}]))`,
        endMs,
      ),
      lokiRange(`sum(count_over_time(${apiStream} [${stepSec}s]))`, startMs, endMs, stepSec),
      lokiRange(
        `quantile_over_time(0.95, ${unwrapMs} [${stepSec}s]) by ()`,
        startMs, endMs, stepSec,
      ),
      // Top 5 slowest endpoints, grouped by host+method (full URL is too
      // high-cardinality and would explode the series limit).
      lokiInstantBySeries(
        `topk(5, quantile_over_time(0.95, ${apiStream} | logfmt | unwrap event_data_duration_ns | __error__="" [${range}]) by (event_data_http_method, event_data_http_host))`,
        endMs,
      ),
    ]);

  const responseTimeMs: PercentileMetric = {
    p50: responseTimeNs.p50 / 1_000_000,
    p75: responseTimeNs.p75 / 1_000_000,
    p95: responseTimeNs.p95 / 1_000_000,
    p99: responseTimeNs.p99 / 1_000_000,
  };
  const total = Math.round(requestCount);
  const ok = Math.round(successCount);
  const errorRate = total > 0 ? ((total - ok) / total) * 100 : 0;
  const successRate = total > 0 ? (ok / total) * 100 : 100;

  // Build trendData from the two parallel matrices (count + p95).
  // TimeSeriesPoint.timestamp is typed `number | string`; coerce to number
  // here so we can use it as a Map key on both sides of the merge.
  const trendByTs = new Map<number, ApiTrendPoint>();
  for (const p of trendCountSeries) {
    const ts = typeof p.timestamp === 'number' ? p.timestamp : Number(p.timestamp);
    trendByTs.set(ts, {
      timestamp: new Date(ts).toISOString(),
      p50: 0,
      p95: 0,
      count: Math.round(p.value),
    });
  }
  for (const p of trendP95SeriesNs) {
    const ts = typeof p.timestamp === 'number' ? p.timestamp : Number(p.timestamp);
    const entry = trendByTs.get(ts);
    const p95Ms = p.value / 1_000_000;
    if (entry) {
      entry.p95 = p95Ms;
      entry.p50 = p95Ms * 0.5; // approximation; cheap and "good enough" for a sparkline
    }
  }
  const trendData: ApiTrendPoint[] = [...trendByTs.values()].sort(
    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
  );

  const slowestEndpoints: ApiEndpointSummary[] = slowestVec.map((s) => ({
    endpoint: s.labels?.event_data_http_url || s.labels?.event_data_http_host || '(grouped)',
    method: s.labels?.event_data_http_method || 'GET',
    p95: s.value / 1_000_000,
    count: 0,
    successRate: 100,
  }));

  return {
    responseTime: responseTimeMs,
    requestCount: total,
    successRate: Math.round(successRate * 10) / 10,
    errorRate: Math.round(errorRate * 10) / 10,
    slowestEndpoints,
    trendData,
  };
}

