/* -------------------------------------------------------------------------
 * 8. Browser Analytics
 *    Browsers/OS distribution: sum by (label) (count_over_time(...))
 *    Unique sessions:          same as getUserActivity
 * ------------------------------------------------------------------------- */

export async function getBrowserAnalytics(params: FaroQueryParams): Promise<BrowserAnalyticsData> {
  if (!isFaroAvailable()) throw new Error('Browser Analytics data unavailable');
  const range = toLogQLRange(params.timeRange || '24h');
  const rangeMs = parseTimeRange(params.timeRange || '24h');
  const endMs = Date.now();
  const startMs = endMs - rangeMs;
  const stepSec = pickStep(rangeMs);
  // session_start / session_resume events carry one row per activation
  // and include all browser_* labels we need — cheaper than scanning the
  // full RUM stream and doing distinct counting via | logfmt session_id.
  const sessionStartStream = `{source="faro", type="rum", event_name=~"session_start|session_resume"}`;

  const [browsersVec, osVec, mobileVec, totalSessions, browserTrendSeries] =
    await Promise.all([
      lokiInstantBySeries(
        `sum by (browser_name) (count_over_time(${sessionStartStream} | logfmt browser_name [${range}]))`,
        endMs,
      ),
      lokiInstantBySeries(
        `sum by (browser_os) (count_over_time(${sessionStartStream} | logfmt browser_os [${range}]))`,
        endMs,
      ),
      lokiInstantBySeries(
        `sum by (browser_mobile) (count_over_time(${sessionStartStream} | logfmt browser_mobile [${range}]))`,
        endMs,
      ),
      lokiInstant(
        `sum(count_over_time(${sessionStartStream} [${range}]))`,
        endMs,
      ),
      lokiHttp('/query_range', {
        query: `sum by (browser_name) (count_over_time(${sessionStartStream} | logfmt browser_name [${stepSec}s]))`,
        start: String(startMs * 1_000_000),
        end: String(endMs * 1_000_000),
        step: String(stepSec),
      }),
    ]);

  const sessions = Math.round(totalSessions);

  const browsers: BrowserSummary[] = browsersVec
    .filter((b) => b.labels.browser_name)
    .map((b) => ({
      name: b.labels.browser_name,
      sessions: Math.round(b.value),
      percentage: sessions > 0 ? Math.round((b.value / sessions) * 1000) / 10 : 0,
    }))
    .sort((a, b) => b.sessions - a.sessions);

  const operatingSystems: OSSummary[] = osVec
    .filter((o) => o.labels.browser_os)
    .map((o) => {
      const raw = o.labels.browser_os;
      const lower = raw.toLowerCase();
      let name = raw;
      if (lower.includes('mac')) name = 'macOS';
      else if (lower.includes('win')) name = 'Windows';
      else if (lower.includes('linux')) name = 'Linux';
      else if (lower.includes('ios')) name = 'iOS';
      else if (lower.includes('android')) name = 'Android';
      return {
        name,
        sessions: Math.round(o.value),
        percentage: sessions > 0 ? Math.round((o.value / sessions) * 1000) / 10 : 0,
      };
    })
    .sort((a, b) => b.sessions - a.sessions);

  let desktop = 0;
  let mobile = 0;
  for (const m of mobileVec) {
    const isMobile = String(m.labels.browser_mobile || '').toLowerCase() === 'true';
    if (isMobile) mobile += Math.round(m.value);
    else desktop += Math.round(m.value);
  }

  const browserTrend: BrowserTrendPoint[] = [];
  const trendStreams = browserTrendSeries?.data?.result ?? [];
  for (const series of trendStreams) {
    const browser = series.metric?.browser_name ?? 'Unknown';
    for (const [ts, v] of series.values ?? []) {
      browserTrend.push({
        timestamp: new Date(Math.floor(toNumberTs(ts) * 1000)).toISOString(),
        browser,
        sessions: parseFloat(v) || 0,
      });
    }
  }
  browserTrend.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime());

  return {
    browsers,
    deviceTypes: {
      desktop,
      mobile,
      desktopPercentage: sessions > 0 ? Math.round((desktop / sessions) * 1000) / 10 : 0,
      mobilePercentage: sessions > 0 ? Math.round((mobile / sessions) * 1000) / 10 : 0,
    },
    operatingSystems,
    totalSessions: sessions,
    browserTrend,
  };
}

